export const TOPICS_A = [
  { id: 'a001', cat: 'Догматика', title: 'Какво е православно богословие', text: 'За светите отци богословието не е само академична наука, а живо познание на Бога, което се ражда от молитва и чист живот. Св. Евагрий казва, че богослов е онзи, който се моли истински, а който се моли истински, е богослов. Затова вярата не се изучава само с ума, а и със сърцето, с участие в тайнствата и с борба срещу страстите. Догматите не са сухи формули, а граници, които пазят истината за Бога и за спасението ни. Всеки ден, в който се учиш на вярата и я живееш, е крачка към Онзи, за Когото говорим.', read: 'Йоан 17:3; св. Григорий Богослов, Слово 27 (Първо богословско слово)' },
  { id: 'a002', cat: 'Тайнства и богослужение', title: 'Какво е тайнство', text: 'Тайнството е свещенодействие, в което чрез видим знак се дава невидимата благодат на Светия Дух. Православната църква обикновено изброява седем тайнства: Кръщение, Миропомазание, Евхаристия, Покаяние, Свещенство, Брак и Елеосвещение. Гръцката дума „мистирион“ подсказва, че тук действа Бог по начин, който надхвърля нашето разбиране. Тайнствата не са магия – те изискват вяра и готовност на сърцето. Чрез тях Христос продължава да докосва и изцелява хората, както в евангелските времена.', read: 'Йоан 3:5; св. Николай Кавасила, „Животът в Христос“' },
  { id: 'a003', cat: 'Свещено Писание', title: 'Какво е Библията', text: 'Библията (от гр. „книги“) е сборник от свещени книги, написани от хора, вдъхновени от Светия Дух. Тя се дели на Стар Завет – времето на подготовката за идването на Спасителя, и Нов Завет – който разказва за Христос и Неговата Църква. Новият Завет съдържа 27 книги, а православната Библия включва в Стария Завет и т.нар. неканонични книги (като Товит, Премъдрост Соломонова и Макавеите), които се четат за назидание. Целият Стар Завет води към Христос, а Новият разкрива Неговото дело. Библията не е учебник по природни науки, а книга за спасението.', read: '2 Тим. 3:14-17; Лука 24:27' },
  { id: 'a004', cat: 'Догматика', title: 'Божественото Откровение', text: 'Човек не би могъл сам да познае Бога в Неговата пълнота, затова Бог Сам се открива на хората. Има естествено откровение – чрез творението и съвестта, и свръхестествено – чрез пророците и най-вече чрез Иисус Христос. Това Откровение е запазено в Църквата по два начина: в Свещеното Писание и в Свещеното Предание. Те не си противоречат, а са един поток на една и съща истина, воден от Светия Дух. Затова православният християнин чете Библията не сам, а в общението на Църквата.', read: 'Евр. 1:1-2; Римл. 1:19-20' },
  { id: 'a005', cat: 'Тайнства и богослужение', title: 'Светото Кръщение', text: 'Кръщението е вратата към Църквата и към целия християнски живот. В него човекът се потапя три пъти във водата в името на Отца и Сина и Светия Дух – умира за греха и се ражда за нов живот с Христос. Прощават се всички грехове и човекът става член на Тялото Христово. Преди това той (или кръстникът му) се отрича от сатаната и се съчетава с Христос, като чете Символа на вярата. Кръстникът поема отговорност да възпита кръщелника във вярата.', read: 'Римл. 6:3-11; св. Кирил Йерусалимски, „Тайноводствени поучения“' },
  { id: 'a006', cat: 'Свещено Писание', title: 'Септуагинта', text: 'Септуагинта (Превод на седемдесетте) е древен гръцки превод на Стария Завет, направен в Александрия няколко века преди Христос. Апостолите и ранната Църква най-често цитират Стария Завет именно по нея. Православната църква и до днес я смята за авторитетен текст на Стария Завет. Някои важни пророчества за Христос са особено ясни в нея – например в Ис. 7:14 се говори за „Дева“, която ще роди. Затова номерацията на псалмите в православната Библия често се различава с единица от тази в протестантските издания.', read: 'Ис. 7:14; Мат. 1:22-23' },
  { id: 'a007', cat: 'Догматика', title: 'Свещеното Предание', text: 'Свещеното Предание е животът на Светия Дух в Църквата, предаван от апостолите до днес. То включва Символа на вярата, решенията на Вселенските събори, богослужението, писанията на светите отци и иконите. Самото Писание се е родило в Преданието – Църквата е определила кои книги са богодухновени. Апостол Павел изрично заповядва да пазим преданията, научени и с думи, и чрез послание. Преданието не е мъртва традиция на обичаи, а живата памет на Църквата за Христос.', read: '2 Сол. 2:15; св. Викентий Лерински, „Паметни бележки“' },
  { id: 'a008', cat: 'Тайнства и богослужение', title: 'Светото Миропомазание', text: 'Веднага след Кръщението православните получават тайнството Миропомазание. Свещеникът помазва със свето миро челото, очите, ноздрите, устата, ушите, гърдите, ръцете и краката, като казва: „Печат на дара на Светия Дух“. Това е личната Петдесетница на всеки християнин. Светото миро се приготвя от много благоуханни вещества и се освещава от висшата църковна власт. Миропомазаният е призван да пази дара на Духа като печат на своята принадлежност към Христос.', read: 'Деян. 8:14-17; 2 Кор. 1:21-22' },
  { id: 'a009', cat: 'Свещено Писание', title: 'Как Църквата чете Писанието', text: 'Православният християнин чете Библията не като частен изследовател, а като член на Църквата, в която е написана. Тълкуванието на светите отци е като карта, която ни пази от изкривяване на смисъла. Ап. Петър предупреждава, че никое пророчество в Писанието не се тълкува по собствено разбиране. Добре е преди четене да се помолиш за просветление, да четеш бавно и да прилагаш прочетеното в живота. Започни с Новия Завет – с Евангелията – и чети по малко всеки ден.', read: '2 Петр. 1:20-21; 2 Петр. 3:15-16' },
  { id: 'a010', cat: 'Догматика', title: 'Непознаваемият Бог', text: 'Православното богословие учи, че Бог по Своята същност е напълно непостижим за всяко създание. Затова отците често говорят за Него чрез отрицание: Бог е невидим, безначален, неизменен, неописуем – това е т.нар. апофатично богословие. Мойсей среща Бога в мрака на Синай, което отците тълкуват като образ на това, че Бог е над всяко човешко понятие. Но същият Бог, Който е непознаваем, се дава да бъде познат в любов, молитва и смирение. Тази истина пази вярата ни от гордостта да мислим, че сме „разбрали“ Бога.', read: 'Изх. 20:21; св. Григорий Нисийски, „Животът на Мойсей“' },
  { id: 'a011', cat: 'Тайнства и богослужение', title: 'Светата Евхаристия', text: 'Евхаристията (гр. „благодарение“) е тайнството на тайнствата, в което хлябът и виното стават истинско Тяло и истинска Кръв Христови. Христос я установи на Тайната вечеря, като каза: „Това е Моето тяло… Това е Моята кръв“. Причастявайки се, ние се съединяваме с Христос и помежду си в едно Тяло. Св. Игнатий Богоносец нарича Причастието „лекарство за безсмъртие“. Без Евхаристията християнският живот е като тяло без храна.', read: 'Йоан 6:53-58; 1 Кор. 11:23-29' },
  { id: 'a012', cat: 'Свещено Писание', title: 'Шестте дни на творението', text: 'Първата глава на Битие описва сътворението на света в шест дни, като на седмия Бог почива. Текстът подчертава, че всичко е създадено от Бога по Неговото Слово, в ред и красота, и че всичко е „твърде добро“. Венец на творението е човекът, създаден по образ Божий. Отците, като св. Василий Велики в „Шестоднев“, тълкуват тези глави с благоговение и дълбочина. Главното послание не е техническо, а богословско: светът не е случаен, а е дар от любящия Създател.', read: 'Бит. 1-2; св. Василий Велики, „Шестоднев“' },
  { id: 'a013', cat: 'Догматика', title: 'Свойствата на Бога', text: 'Писанието и отците говорят за Бога като вечен, всемогъщ, вездесъщ, всезнаещ, благ и свят. Вечен означава, че Той няма начало и край и стои над времето, което Сам е създал. Вездесъщ означава, че няма място, където Него да Го няма – нито в залата, нито на ринга, нито в най-тъмния ти час. Най-дълбокото обаче, което Писанието казва, е, че Бог е любов. Всички други свойства трябва да се разбират в светлината на тази любов, а не като студена сила.', read: '1 Йоан 4:8-16; Пс. 138' },
  { id: 'a014', cat: 'Тайнства и богослужение', title: 'Тайнството Изповед', text: 'В тайнството Изповед (Покаяние) християнинът изповядва греховете си пред Бога в присъствието на свещеника и получава опрощение. Свещеникът не е съдия, а свидетел и лекар – както казва молитвата, „ти дойде при лекар, внимавай да не си отидеш неизлекуван“. Христос даде на апостолите властта да прощават греховете. Изповедта трябва да бъде искрена, конкретна, без оправдания и без да обвиняваш другите. След нея човек си тръгва облекчен, защото Бог наистина прощава.', read: 'Йоан 20:22-23; 1 Йоан 1:9' },
  { id: 'a015', cat: 'Свещено Писание', title: 'Първото благовестие', text: 'Веднага след грехопадението Бог казва на змията, че ще постави вражда между нея и жената, и между нейното потомство и потомството на жената. Потомството на жената ще смаже главата на змията. Отците наричат този стих „Първоевангелие“ – първото обещание за Спасителя. Те го тълкуват като пророчество за Христос, роден от Дева, и за Неговата победа над дявола. Още в мига на падението Бог вече е приготвил пътя на спасението.', read: 'Бит. 3:15; Гал. 4:4' },
  { id: 'a016', cat: 'Догматика', title: 'Светата Троица', text: 'Ние вярваме в един Бог в три Лица (Ипостаси) – Отец, Син и Свети Дух. Трите Лица имат една и съща божествена същност, една воля и едно действие, но не се сливат помежду си. Отец е безначален, Синът е роден от Отца преди всички векове, а Светият Дух изхожда от Отца. Троицата не е математическа загадка, а откровение, че Бог в Самия Себе Си е общение на любовта. Затова и Църквата, и християнското семейство са призвани да бъдат икона на това общение.', read: 'Мат. 28:19; св. Григорий Богослов, Слово 31' },
  { id: 'a017', cat: 'Тайнства и богослужение', title: 'Тайнството Свещенство', text: 'Чрез тайнството Свещенство, при ръкополагане от епископ, се дава благодатта за служение в Църквата. Има три степени на свещенство: дякон, презвитер (свещеник) и епископ. Дяконът помага при богослуженията, свещеникът извършва тайнствата (без ръкоположение), а епископът е глава на местната църква и може да ръкополага. Свещеникът е баща в духовен смисъл и затова го наричаме „отче“. Добре е да се молим за свещениците си, защото тяхното бреме е тежко.', read: '1 Тим. 3:1-13; св. Йоан Златоуст, „Шест слова за свещенството“' },
  { id: 'a018', cat: 'Свещено Писание', title: 'Каин и Авел', text: 'Каин и Авел са първите синове на Адам и Ева. Бог приема жертвата на Авел, който принася най-доброто с вяра, но не и тази на Каин. Каин, обзет от завист и гняв, убива брат си – първото убийство в историята. Бог предупреждава Каин, че грехът „лежи пред вратата“, но той трябва да го владее. Това е урок за всеки боец: гневът и завистта трябва да бъдат овладени, преди да те овладеят.', read: 'Бит. 4:1-16; Евр. 11:4' },
  { id: 'a019', cat: 'Догматика', title: 'Бог Отец', text: 'Отец е първото Лице на Светата Троица – безначален и нероден, източник на Сина и на Светия Дух. Отците казват, че Той е „причината“ в Троицата, но не по време или по достойнство, защото трите Лица са равночестни. Иисус Христос ни научи да се обръщаме към Бога с „Отче наш“ – това е дар, който ни прави осиновени синове. Бог Отец не е далечен съдия, а Баща, който тича да прегърне завръщащия се син. Да вярваш в Отца означава да знаеш, че никога не си сирак.', read: 'Лука 15:20; Гал. 4:4-7' },
  { id: 'a020', cat: 'Тайнства и богослужение', title: 'Тайнството Брак', text: 'В тайнството Брак (Венчание) Бог съединява мъжа и жената в едно цяло, по образа на единството на Христос и Църквата. По време на службата на младоженците се поставят венци – знак както на царско достойнство, така и на мъченичество, защото истинската любов изисква жертва. Те пият от обща чаша и обикалят три пъти около аналоя, докато се пее. Христовото първо чудо е станало на сватба в Кана Галилейска. Семейството е „малка Църква“ – място, където се учим на смирение и любов.', read: 'Ефес. 5:21-33; Йоан 2:1-11' },
  { id: 'a021', cat: 'Свещено Писание', title: 'Ной и потопът', text: 'Когато земята се изпълнила с беззаконие, праведният Ной намерил благоволение пред Бога. По Божията заповед той построил ковчег и в него се спасило семейството му и животните. След потопа Бог сключил завет с Ной и поставил дъгата като знак. Отците виждат в ковчега образ на Църквата, в която се спасяваме, а в потопа – образ на Кръщението. Ной е пример за човек, който остава верен на Бога, когато всички около него вървят в обратна посока.', read: 'Бит. 6-9; 1 Петр. 3:20-21' },
  { id: 'a022', cat: 'Догматика', title: 'Синът – Слово Божие', text: 'Второто Лице на Светата Троица е Синът, Когото евангелист Йоан нарича Слово (Логос). Той е роден от Отца извънвремево, вечно, а не създаден, и е единосъщен с Отца. Чрез Словото е сътворен целият свят и чрез Него Бог се открива на хората. В пълнотата на времето същото това Слово стана човек – Иисус Христос. Затова, когато гледаме Христос в Евангелието, ние виждаме лицето на Самия Бог.', read: 'Йоан 1:1-18; Кол. 1:15-17' },
  { id: 'a023', cat: 'Тайнства и богослужение', title: 'Елеосвещение', text: 'Елеосвещението (Маслосвет) е тайнство за изцеление на болните душевно и телесно. Свещениците помазват болния с осветен елей и се молят за изцелението му и за опрощаване на греховете. По традиция се извършва от седем свещеници, но може да се извърши и от по-малко. Това тайнство не е само за умиращите, а за всеки болен. В много храмове то се извършва общо за енориашите по време на Великия пост.', read: 'Як. 5:14-15; Марк 6:13' },
  { id: 'a024', cat: 'Свещено Писание', title: 'Авраам – отец на вярващите', text: 'Бог призова Авраам да напусне земята и рода си и да тръгне към страна, която още не знаел. Авраам послушал и тръгнал – и затова е наречен „отец на всички вярващи“. Бог му обещал потомство, многобройно като звездите, макар той и Сара да били стари. Писанието казва, че Авраам повярвал на Бога и това му се вменило в праведност. Вярата му не е теоретична, а смелост да тръгнеш, когато Бог те повика.', read: 'Бит. 12:1-4; Евр. 11:8-12' },
  { id: 'a025', cat: 'Догматика', title: 'Светият Дух', text: 'Светият Дух е третото Лице на Светата Троица, истинен Бог, равен на Отца и Сина. Той изхожда от Отца и е изпратен в света чрез Сина в деня на Петдесетница. Духът е „Утешител“ и „Дух на истината“ – Той дава живот, освещава тайнствата и прави Църквата жива. Св. Серафим Саровски казва, че целта на християнския живот е придобиването на Светия Дух. Затова всяка молитва в Православната църква обикновено започва с „Царю небесни“ – призоваване на Духа.', read: 'Йоан 14:16-17, 26; св. Василий Велики, „За Светия Дух“' },
  { id: 'a026', cat: 'Тайнства и богослужение', title: 'Божествената литургия', text: 'Божествената литургия е главното православно богослужение, в което се извършва тайнството Евхаристия. Думата „литургия“ означава „общо дело“ – тя не е представление, а действие на целия Божи народ. Литургията има две основни части: Литургия на оглашените, в която се чете Словото Божие, и Литургия на верните, в която се принасят и осветяват Даровете. Преди нея свещеникът извършва подготвителната част – Проскомидия. В неделя и празник Църквата се събира около Христос, както апостолите на Тайната вечеря.', read: 'Деян. 2:42; св. Николай Кавасила, „Изъяснение на Божествената литургия“' },
  { id: 'a027', cat: 'Свещено Писание', title: 'Жертвоприношението на Исаак', text: 'Бог изпитал Авраам, като му заповядал да принесе в жертва единствения си син Исаак. Авраам тръгнал с послушание, а Исаак сам носел дървата нагоре по планината. В последния момент ангел спрял ръката на Авраам и Бог осигурил овен за жертва. Отците виждат тук образ на Христос – единствения Син, Който Сам носи Кръста Си към Голгота. Това, от което Бог пощади Авраам, Той Сам не пощади – Своя Син.', read: 'Бит. 22:1-18; Римл. 8:32' },
  { id: 'a028', cat: 'Догматика', title: 'Изхождането на Светия Дух', text: 'Символът на вярата казва, че Светият Дух изхожда от Отца – така, както е казал Сам Христос в Евангелието. На Запад по-късно към Символа е добавено, че Духът изхожда „и от Сина“ (лат. Filioque). Православната църква не приема тази добавка, защото променя текста, утвърден от Вселенските събори, и нарушава учението, че Отец е единственият източник в Троицата. Православните отци разграничават вечното изхождане на Духа от Отца и временното Му изпращане в света чрез Сина. Това не е спор за една дума, а за точността на вярата в Бога.', read: 'Йоан 15:26; св. Фотий Цариградски, „Мистагогия на Светия Дух“' },
  { id: 'a029', cat: 'Тайнства и богослужение', title: 'Литургиите на светите отци', text: 'В Православната църква се служат три литургии. Най-често това е литургията на св. Йоан Златоуст. Литургията на св. Василий Велики, с по-дълги молитви, се служи десет пъти в годината – в неделите на Великия пост, на Велики четвъртък и Велика събота, в навечерието на Рождество и Богоявление и на 1 януари. Литургията на Преждеосвещените Дарове се служи в делнични дни на Великия пост. Различията са главно в тайните молитви на свещеника, а сърцевината е една и съща.', read: 'Лука 22:19-20; св. Василий Велики, Литургия (анафора)' },
  { id: 'a030', cat: 'Свещено Писание', title: 'Яков се бори с Бога', text: 'Една нощ, преди срещата с брат си Исав, Яков останал сам и Някой се борил с него до зори. Яков не пускал противника си, докато не получил благословение. Тогава му било дадено ново име – Израил, което се тълкува като „борил се с Бога“. Яков останал с повредено бедро, но благословен. Отците виждат тук образ на молитвата – упорита, неотстъпваща борба, в която човек не пуска Бога, докато не получи Неговата благодат.', read: 'Бит. 32:24-30; Ос. 12:3-4' },
  { id: 'a031', cat: 'Догматика', title: 'Същност и енергии', text: 'Православната църква различава в Бога непознаваема същност и нетварни енергии (действия). Същността на Бога остава недостъпна завинаги, но Неговите енергии – благодатта, светлината, любовта – са истински Бог, Който излиза към нас. Затова човек може реално да се съедини с Бога, без да се слее с Неговата природа. Това учение е изяснено особено от св. Григорий Палама през XIV век и е потвърдено от събори в Цариград. То прави възможно онова, което отците наричат обожение.', read: '2 Петр. 1:4; св. Григорий Палама, „Триади в защита на свещенобезмълвстващите“' },
  { id: 'a032', cat: 'Тайнства и богослужение', title: 'Преждеосвещената литургия', text: 'В делничните дни на Великия пост пълна литургия не се служи, защото тя е празнична по своя дух. Вместо това в сряда и петък се служи Литургия на Преждеосвещените Дарове – вечерна служба, в която вярващите се причастяват с Дарове, осветени предварително в неделя. Традицията свързва тази литургия с името на св. Григорий Двоеслов. Тя е тиха и покайна, с много поклони и пеене на „Да се изправи молитвата ми като кадило пред Тебе“. Добре е поне веднъж в поста да я посетиш.', read: 'Пс. 140:2; Йоан 6:51' },
  { id: 'a033', cat: 'Свещено Писание', title: 'Йосиф Прекрасни', text: 'Йосиф, любимият син на Яков, бил продаден от завистливите си братя в Египет. Там той устоял на изкушението на жената на Потифар, бил несправедливо хвърлен в тъмница, но накрая станал втори след фараона. Когато братята му дошли гладни, той им простил и казал, че те са намислили зло, но Бог го е обърнал за добро. Църквата помни Йосиф на Велики понеделник като образ на страдащия и прощаващ Христос. Неговата история учи на чистота, търпение и прошка.', read: 'Бит. 37; 39; 45; 50:15-21' },
  { id: 'a034', cat: 'Догматика', title: 'Нетварната светлина', text: 'На планината Тавор апостолите видели Христос да сияе в светлина, по-ярка от слънцето. Православната църква учи, че това не е била създадена, физическа светлина, а сиянието на Самото Божество. Тази светлина са виждали и много светии в молитва – например св. Серафим Саровски пред Мотовилов. Тя е обещание, че и праведниците ще светнат в Царството на своя Отец. Тя ни напомня, че християнството не е само морал, а преображение на целия човек.', read: 'Мат. 17:1-9; Мат. 13:43' },
  { id: 'a035', cat: 'Тайнства и богослужение', title: 'Проскомидията', text: 'Проскомидията е първата част на Литургията, която свещеникът извършва в олтара, обикновено преди началото на общата служба. От просфорите той изважда Агнеца – частта, която ще стане Тяло Христово, и я полага на дискоса. Около нея се поставят частици в чест на Богородица, светиите, както и за живите и починалите. Затова, когато подаваш поменик с имена, те буквално се споменават пред Христовата жертва. В края на Литургията тези частици се потапят в Чашата с молитва за опрощение.', read: 'Ис. 53:7; св. Николай Кавасила, „Изъяснение на Божествената литургия“' },
  { id: 'a036', cat: 'Свещено Писание', title: 'Мойсей и горящата къпина', text: 'Докато пасял овце в пустинята, Мойсей видял къпина, която гори, но не изгаря. От къпината Бог му проговорил, заповядал му да събуе обувките си, защото мястото е свято, и го изпратил да изведе Израил от Египет. Там Бог открил и Своето име – „Аз съм Сущият“. Църквата вижда в неизгарящата къпина образ на Богородица, която носи в себе си Божия огън, без да изгори. Мойсей, макар да се смятал за недостоен, бил укрепен от Бога за велико дело.', read: 'Изх. 3:1-15; св. Григорий Нисийски, „Животът на Мойсей“' },
  { id: 'a037', cat: 'Догматика', title: 'Сътворението от нищо', text: 'Бог е създал света не от някакъв предвечен материал, а от нищо, само по Своята воля и любов. Светът не е част от Бога, но не е и случаен – той носи отпечатъка на Божията мъдрост. В Битие след всеки ден на творението се казва, че Бог видя, че е добро. Затова православните християни не презират материята и тялото, а ги виждат като дар, който трябва да бъде осветен. Човекът е поставен в света като негов свещеник и стопанин, а не като негов тиранин.', read: 'Бит. 1; 2 Мак. 7:28' },
  { id: 'a038', cat: 'Тайнства и богослужение', title: 'Началото на Литургията', text: 'Литургията започва с възгласа: „Благословено е Царството на Отца и Сина и Светия Дух“. Тези думи показват, че от този момент ние вече се намираме в преддверието на Божието Царство. След това дяконът или свещеникът произнася Великата (мирна) ектения – поредица от молитвени прошения за мира, Църквата, държавата, пътуващите, болните. Народът отговаря с „Господи, помилуй“. Тази молитва ни учи, че християнинът не се моли само за себе си, а за целия свят.', read: '1 Тим. 2:1-2; Мат. 6:33' },
  { id: 'a039', cat: 'Свещено Писание', title: 'Изходът и старозаветната Пасха', text: 'Бог изведе израилтяните от египетското робство с могъща ръка. В нощта на изхода всяко семейство заклало агне и помазало вратите с кръвта му, за да ги отмине ангелът на смъртта. След това народът преминал по сухо през Червено море. Всичко това е образ на Христос – истинския Пасхален Агнец, чиято кръв ни избавя от смъртта. Преминаването през морето е образ на Кръщението, което ни извежда от робството на греха.', read: 'Изх. 12; 14; 1 Кор. 5:7' },
  { id: 'a040', cat: 'Догматика', title: 'Ангелите', text: 'Ангелите са безплътни, разумни духове, създадени от Бога преди видимия свят. Тяхното име означава „вестители“ – те служат на Бога и на спасението на хората. Църквата учи, че всеки кръстен християнин има свой ангел-пазител. Св. Дионисий Ареопагит описва девет ангелски чина – от Серафимите до Ангелите. На 8 ноември Църквата празнува Събора на архистратиг Михаил и другите безплътни сили – добър ден да благодариш за невидимата закрила.', read: 'Евр. 1:14; Мат. 18:10' },
  { id: 'a041', cat: 'Тайнства и богослужение', title: 'Антифони и Малък вход', text: 'След ектенията се пеят антифони – псалми или техни стихове, а в неделни и празнични дни често и Блаженствата. Пее се и химнът „Единородни Сине“, изповядващ Въплъщението. Следва Малкият вход: свещеникът излиза с Евангелието и влиза в олтара през царските двери. Това символизира излизането на Христос на проповед. Народът пее: „Елате да се поклоним и да припаднем към Христа“.', read: 'Мат. 5:3-12; Пс. 94:6' },
  { id: 'a042', cat: 'Свещено Писание', title: 'Десетте Божии заповеди', text: 'На планината Синай Бог даде на Мойсей Десетте заповеди, написани на две каменни плочи. Първите заповеди говорят за отношението към Бога, а останалите – за отношението към ближния. Те не са произволни правила, а пътеводител към свобода и живот. Христос не отмени заповедите, а ги задълбочи – Той забранява не само убийството, но и гнева, не само прелюбодейството, но и похотливия поглед. Цялият Закон, казва Христос, се събира в две заповеди: любов към Бога и любов към ближния.', read: 'Изх. 20:1-17; Мат. 22:36-40' },
  { id: 'a043', cat: 'Догматика', title: 'Падналите духове', text: 'Част от ангелите, водени от Луцифер, по своя свободна воля се отвърнали от Бога в гордост и станали демони. Злото не е създадено от Бога, а е изкривяване на доброто чрез злоупотреба със свободата. Дяволът изкушава, лъже и разделя, но няма власт над човек, който е с Христос и не му отваря врата. Оръжията в тази невидима борба са молитвата, постът, смирението, тайнствата и кръстният знак. Христос вече е победил – нашата задача е да стоим в Неговата победа.', read: 'Ефес. 6:10-18; Як. 4:7' },
  { id: 'a044', cat: 'Тайнства и богослужение', title: 'Трисветата песен', text: 'След Малкия вход се пее „Святий Боже, Святий Крепкий, Святий Безсмъртний, помилуй нас“. Тази песен е много древна и се свързва с ангелското славословие пред Божия престол. Тя е изповед на Троицата и на Божията сила, но също и смирен вик за милост. На някои големи празници вместо нея се пее „Елицы во Христа крестистеся“ – „Които в Христа се кръстихте, в Христа се облякохте“. Трисветата песен е и част от всекидневните начални молитви.', read: 'Ис. 6:3; Откр. 4:8' },
  { id: 'a045', cat: 'Свещено Писание', title: 'Скинията', text: 'В пустинята Бог заповядал на Мойсей да построи скиния – преносим храм, в който Бог обитавал сред народа Си. В най-вътрешната част, Светая Светих, стоял Ковчегът на завета с плочите на Закона. Всичко в скинията било направено по образеца, показан на Мойсей на планината. Посланието към евреите обяснява, че скинията е сянка и образ на небесното и на Христовото дело. Църквата вижда в Ковчега на завета и образ на Богородица, която носи в себе си Самия Законодател.', read: 'Изх. 25:8-22; Евр. 9:1-14' },
  { id: 'a046', cat: 'Догматика', title: 'Образ и подобие Божие', text: 'Бог създал човека по Свой образ и по Свое подобие. Отците обясняват, че образът е даден на всеки – разумът, свободата, способността да обичаш и да твориш. Подобието е задача: човек трябва с Божията помощ да израсне в святост и да стане подобен на Бога. Затова всеки човек, дори противникът срещу теб, носи Божия образ и заслужава уважение. Духовният живот е тренировка, в която образът постепенно се превръща в подобие.', read: 'Бит. 1:26-27; св. Григорий Нисийски, „За устройството на човека“' },
  { id: 'a047', cat: 'Тайнства и богослужение', title: 'Апостолът и Евангелието', text: 'В Литургията на оглашените се четат откъси от Апостола (Деяния и посланията) и от Евангелието. Преди Апостола се пее прокимен – кратък стих от псалом, а след него – „Алилуия“ със стихове. Всички стоят прави при четенето на Евангелието, защото в него Самият Христос ни говори. След това често следва проповед, която разяснява прочетеното. Ако искаш да се подготвиш, добре е предварително да прочетеш у дома евангелското четиво за деня.', read: 'Лука 4:16-21; Римл. 10:17' },
  { id: 'a048', cat: 'Свещено Писание', title: 'Иисус Навин', text: 'След смъртта на Мойсей Иисус Навин поел водачеството на Израил и го въвел в Обетованата земя. Бог многократно му казал да бъде твърд и мъжествен и да не се страхува, защото Той е с него. Народът преминал Йордан по сухо, а стените на Йерихон паднали не чрез сила, а чрез послушание и молитва. Името Иисус означава „Господ спасява“ – същото име носи и Христос. Отците виждат в Навин образ на Христос, Който ни въвежда в истинската Обетована земя – Царството Божие.', read: 'Нав. 1:1-9; Нав. 6' },
  { id: 'a049', cat: 'Догматика', title: 'Душата и тялото', text: 'Човекът не е душа, затворена в тяло, а единство от душа и тяло. Душата е безсмъртна, създадена от Бога, а тялото е храм на Светия Дух. Затова Църквата не учи на презрение към тялото, а на неговото подчиняване на духа – чрез пост, въздържание и труд. При смъртта душата и тялото временно се разделят, а при всеобщото възкресение тялото ще бъде възстановено и преобразено. Грижата за тялото е добра, когато служи на душата, а не я поробва.', read: '1 Кор. 6:19-20; 1 Кор. 9:24-27' },
  { id: 'a050', cat: 'Тайнства и богослужение', title: 'Оглашени и верни', text: 'В древната Църква оглашените – хора, които се подготвят за кръщение – присъствали само на първата част на Литургията. Преди Евхаристийния канон дяконът възглася „Оглашени, излезте“. Днес това напомня, че Евхаристията е тайнство на кръстените и подготвените. Втората част, Литургия на верните, е посветена изцяло на принасянето и освещаването на Даровете. Тя ни призовава да не бъдем случайни зрители, а участници.', read: 'Деян. 2:41-42; св. Кирил Йерусалимски, „Огласителни поучения“, Предговор' },
  { id: 'a051', cat: 'Свещено Писание', title: 'Гедеон и тристата мъже', text: 'Гедеон бил обикновен човек от незначително семейство, когато Ангел Господен го нарекъл „силен и храбър“. Бог го изпратил да спаси Израил от мадиамците, но намалил войската му от хиляди на едва триста души. Целта била всички да разберат, че победата идва от Бога, а не от численото превъзходство. Чудото с руното, което се намокрило от роса, докато земята наоколо била суха, Църквата приема за образ на Богородица. Гедеон ни учи, че Бог избира слабите, за да покаже Своята сила.', read: 'Съд. 6:11-40; Съд. 7' },
  { id: 'a052', cat: 'Догматика', title: 'Свободната воля', text: 'Бог е създал човека свободен, защото любов без свобода не е възможна. Той не насилва никого да Го обича, а чака и кани. Затова дори благодатта Божия действа заедно със свободното съгласие на човека. Свободата е голям дар, но и отговорност – ние избираме посоката на живота си всеки ден, в малките решения. Истинската свобода, според отците, е не да правиш каквото искаш, а да не си роб на страстите.', read: 'Втор. 30:19; Гал. 5:1, 13' },
  { id: 'a053', cat: 'Тайнства и богослужение', title: 'Херувимската песен', text: 'В началото на Литургията на верните се пее Херувимската песен: „Ние, които тайнствено изобразяваме херувимите…“. Тя ни призовава да оставим настрана всяка житейска грижа, за да посрещнем Царя на всичко. Междувременно свещеникът кади и се моли тихо, като признава, че никой не е достоен да служи на Царя на славата. Песента изразява, че на Литургията ние стоим заедно с ангелите. Когато я чуеш, опитай се за миг да оставиш тревогите си.', read: 'Ис. 6:1-3; Евр. 12:22-24' },
  { id: 'a054', cat: 'Свещено Писание', title: 'Давид и Голиат', text: 'Когато великанът Голиат предизвикал Израил, всички войници се уплашили, освен младия овчар Давид. Той отказал тежката броня на цар Саул и излязъл само с прашка и пет камъчета. Давид казал на Голиат, че идва срещу него не с меч, а в името на Господа Саваот. С един камък Давид повалил великана. Това е пример за смелост, която не идва от самоувереност, а от доверие в Бога.', read: '1 Цар. 17; Пс. 143:1' },
  { id: 'a055', cat: 'Догматика', title: 'Грехопадението', text: 'Адам и Ева били създадени в общение с Бога, но по съвета на змията нарушили Божията заповед. Същността на греха им не е самият плод, а желанието да станат „като богове“ без Бога и непослушанието. Резултатът бил отчуждение от Бога, срам, страх и навлизане на смъртта в света. Отците виждат в грехопадението болест на цялата човешка природа, а не просто юридическо провинение. Още в самия момент на падението Бог обещава Спасител, Който ще смаже главата на змията.', read: 'Бит. 3; Римл. 5:12-19' },
  { id: 'a056', cat: 'Тайнства и богослужение', title: 'Великият вход', text: 'По време на Херувимската песен свещеникът и дяконът пренасят Даровете – хляба и виното – от жертвеника към светия престол през царските двери. Това се нарича Велик вход. По пътя свещеникът споменава епископа, властите и всички православни християни. Отците виждат в това шествие образ на Христос, Който доброволно отива към страданията Си. Даровете се полагат на престола и се покриват с покров, както тялото на Христос било положено в гроба.', read: 'Йоан 10:17-18; Лука 23:42' },
  { id: 'a057', cat: 'Свещено Писание', title: 'Падението и покаянието на Давид', text: 'Цар Давид, наречен „човек по сърцето на Бога“, паднал тежко: взел жената на Урия и организирал смъртта на мъжа ѝ. Пророк Натан дошъл при него с притча за богаташ, отнел единствената овчица на бедняка, и казал: „Ти си този човек“. Давид не се оправдал, а веднага признал: „Съгреших пред Господа“. От това покаяние се ражда Псалом 50. Историята показва, че и великите падат, но величието на Давид е в искреното му покаяние.', read: '2 Цар. 11-12; Пс. 50' },
  { id: 'a058', cat: 'Догматика', title: 'Прародителският грях', text: 'Православната църква учи, че от Адам наследяваме не неговата лична вина, а последиците от греха – смъртността, тлението и склонността към грях. Това е като наследствена болест, която засяга цялата човешка природа. Затова и бебетата се кръщават – не защото са виновни, а за да бъдат изцелени и присадени към Христос. Всеки човек обаче носи отговорност за собствените си грехове. Христос, Новият Адам, взе нашата природа, за да я излекува отвътре.', read: 'Римл. 5:12; 1 Кор. 15:21-22' },
  { id: 'a059', cat: 'Тайнства и богослужение', title: '„Да се възлюбим един другиго“', text: 'Преди Символа на вярата свещеникът възглася: „Да се възлюбим един другиго, за да изповядваме единомислено“. Народът отговаря: „Отца и Сина и Светия Дух, Троица единосъщна и неразделна“. Това напомня, че истинската вяра е неотделима от любовта към брата. След това се казва „Двери, двери, с мъдрост да внимаваме“ – в древността така се пазели вратите на храма. Христос казва, че ако имаме нещо против брат си, първо трябва да се примирим с него.', read: 'Мат. 5:23-24; Йоан 13:34-35' },
  { id: 'a060', cat: 'Свещено Писание', title: 'Соломон и мъдростта', text: 'Когато Бог казал на младия цар Соломон да поиска каквото пожелае, той не поискал богатство или победа над враговете, а мъдро сърце, за да управлява справедливо. Бог му дал мъдрост, а с нея и богатство и слава. Соломон построил Йерусалимския храм и се смята за автор на книгите Притчи, Еклесиаст и Песен на песните. В края на живота си обаче той се увлякъл по чужди жени и техните богове. Урокът е, че мъдростта трябва да се пази чрез смирение до края.', read: '3 Цар. 3:5-14; Притч. 1:7' },
  { id: 'a061', cat: 'Догматика', title: 'Божият промисъл', text: 'Бог не е създал света и после да го е изоставил – Той непрестанно го пази и води към добро. Това се нарича Божи промисъл. Дори злото, което хората правят, Бог може да обърне за добро, както станало с Йосиф, продаден от братята си. Христос казва, че и косите на главата ни са преброени. Тази вяра не ни прави пасивни, а ни дава мир: правиш каквото зависи от теб, а останалото поверяваш на Бога.', read: 'Мат. 10:29-31; Бит. 50:20' },
  { id: 'a062', cat: 'Тайнства и богослужение', title: 'Анафората', text: 'Анафората (Евхаристийният канон) е сърцето на Литургията. Започва с призива „Да застанем добре, да застанем със страх“ и „Горе да имаме сърцата“. Свещеникът благодари на Бога за всичко – за творението, за спасението, за Литургията. Народът пее ангелската песен „Свят, свят, свят Господ Саваот“. После се припомнят думите на Христос от Тайната вечеря и Даровете се принасят на Бога с думите „Твое от Твоите“.', read: 'Ис. 6:3; 1 Кор. 11:23-26' },
  { id: 'a063', cat: 'Свещено Писание', title: 'Пророк Илия', text: 'Пророк Илия е един от най-ревностните служители на Бога в Стария Завет. На планината Кармил той се изправил сам срещу стотици жреци на Ваал и Бог отговорил на молитвата му с огън от небето. След това, уплашен и уморен, избягал в пустинята, където Бог го укрепил с храна и му се явил не в бурята, а в тих и кротък полъх. Илия бил взет жив на небето с огнена колесница. Българската църква го почита на 20 юли – Илинден.', read: '3 Цар. 18-19; 4 Цар. 2:1-11' },
  { id: 'a064', cat: 'Догматика', title: 'Въплъщението', text: 'Вечният Син Божи стана човек от Светия Дух и Дева Мария, без да престане да бъде Бог. Това е сърцето на християнската вяра – Бог не просто ни изпраща послания, а Сам идва при нас. Св. Атанасий Велики казва, че Бог стана човек, за да стане човекът бог по благодат. Въплъщението освещава цялата човешка природа – тялото, труда, болката, приятелството. Няма нищо човешко, освен греха, което Христос да не е взел, за да го изцели.', read: 'Йоан 1:14; св. Атанасий Велики, „За въплъщението на Словото“' },
  { id: 'a065', cat: 'Тайнства и богослужение', title: 'Епиклезата', text: 'Епиклезата е призоваването на Светия Дух върху Даровете. Свещеникът се моли Бог да изпрати Духа Си „върху нас и върху тези предложени Дарове“ и да ги направи Тяло и Кръв Христови. Според православното учение именно в този момент, чрез действието на Духа, става претворяването на Даровете. Ние се покланяме дълбоко, защото пред нас е Самият Христос. Това е най-святият миг на Литургията.', read: 'Лука 1:35; св. Йоан Дамаскин, „Точно изложение на православната вяра“, кн. 4' },
  { id: 'a066', cat: 'Свещено Писание', title: 'Йов и тайната на страданието', text: 'Праведният Йов загубил за кратко време богатството, децата и здравето си. Въпреки това той казал: „Господ даде, Господ взе; да бъде благословено името Господне“. Приятелите му настоявали, че той страда, защото е съгрешил, но Бог показал, че те грешат. Накрая Бог Сам проговорил на Йов и той смирено признал величието на Бога, след което Господ му върнал всичко двойно. Книгата учи, че страданието не винаги е наказание и че верността в изпитанието е велико дело.', read: 'Йов 1-2; Йов 42; Як. 5:11' },
  { id: 'a067', cat: 'Догматика', title: 'Истински Бог и истински Човек', text: 'Четвъртият вселенски събор в Халкидон (451 г.) изповядва, че Христос е едно Лице в две природи – божествена и човешка. Тези природи са съединени неслято, неизменно, неразделно и неразлъчно. Христос не е полубог, нито човек, обитаван от Бога, а Самият Бог Слово, станал истински човек. Затова Той може и да страда като човек, и да побеждава смъртта като Бог. В Неговото Лице се срещат небето и земята.', read: 'Фил. 2:5-11; св. Йоан Дамаскин, „Точно изложение на православната вяра“, кн. 3' },
  { id: 'a068', cat: 'Тайнства и богослужение', title: '„Достойно есть“ и поменаването', text: 'Веднага след освещаването на Даровете Църквата се обръща към Богородица с химна „Достойно е наистина да те облажаваме, Богородице“. Свещеникът споменава светиите, починалите и живите – цялата Църква се събира около Агнеца. На големи празници вместо „Достойно есть“ се пее специален химн за празника (задостойник). Според предание текстът на „Достойно есть“ е предаден от архангел Гавриил на монах в Света гора. Тук виждаме, че Църквата на небето и на земята е една.', read: 'Лука 1:48; Евр. 12:1' },
  { id: 'a069', cat: 'Свещено Писание', title: 'Книгата Псалми', text: 'Псалтирът съдържа 150 псалма – молитвени песни, повечето от които се приписват на цар Давид. В тях има всичко: радост, скръб, покаяние, гняв, страх, надежда и благодарност. Православната църква чете целия Псалтир всяка седмица на богослуженията, а през Великия пост – два пъти седмично. Сам Христос се моли с думите на псалмите, дори на Кръста. Св. Атанасий Велики казва, че в псалмите всеки човек може да намери думи за всяко състояние на душата си.', read: 'Пс. 1; св. Атанасий Велики, „Послание до Марцелин за тълкуването на псалмите“' },
  { id: 'a070', cat: 'Догматика', title: 'Двете воли в Христос', text: 'Шестият вселенски събор (680–681 г.) учи, че Христос има две воли – божествена и човешка, защото има две пълни природи. Човешката Му воля винаги свободно се подчинява на божествената. Най-ясно това се вижда в Гетсиманската градина, когато Той се моли: „Не Моята воля, а Твоята да бъде“. Св. Максим Изповедник пострадал жестоко, защото защитавал тази истина. За нас това значи, че човешката воля не се унищожава от Бога, а се изцелява и съгласува с Него.', read: 'Лука 22:42; св. Максим Изповедник, „Диспут с Пир“' },
  { id: 'a071', cat: 'Тайнства и богослужение', title: '„Отче наш“ и „Светая святим“', text: 'Преди Причастието цялата Църква пее или казва заедно Господнята молитва „Отче наш“. Ние се осмеляваме да наречем Бога Отец, защото чрез Христос сме станали Негови деца. След това свещеникът издига Агнеца и възглася: „Светая святим“ – „Светото на светиите“. Народът отговаря: „Един е Свят, един е Господ, Иисус Христос, за слава на Бога Отца“. С това признаваме, че никой не е свят сам по себе си, а само чрез Христос.', read: 'Мат. 6:9-13; Евр. 10:19-22' },
  { id: 'a072', cat: 'Свещено Писание', title: 'Псалом 50', text: 'Псалом 50 започва с думите „Помилуй ме, Боже, по голямата Твоя милост“ и е най-известната покайна молитва в Църквата. Той е написан от цар Давид след неговото падение и изобличението на пророк Натан. В него няма оправдания – само искрено признание и молба за чисто сърце. Псалмът се чете на почти всяка служба и в утринните молитви. Добре е да го научиш наизуст и да го казваш, когато паднеш.', read: 'Пс. 50; 2 Цар. 12:1-13' },
  { id: 'a073', cat: 'Догматика', title: 'Кръстната жертва', text: 'Христос доброволно пое кръста и смъртта, за да ни избави от греха, дявола и смъртта. Отците описват Кръста с различни образи – като откуп, като жертва, като победа над врага и като изцеление. Важното е, че не Бог Отец е искал отмъщение, а Троицата от любов е спасила човека. На Кръста любовта Божия е стигнала докрай – дотам, че Бог умира за Своите врагове. Затова Кръстът за християнина не е символ на поражение, а знаме на победа.', read: 'Йоан 3:16; 1 Кор. 1:18-25' },
  { id: 'a074', cat: 'Тайнства и богослужение', title: 'Подготовка за Причастие', text: 'Православната традиция изисква подготовка за Светото Причастие – пост, молитва и покаяние. Обичайно се чете последованието за Причастие и се спазва евхаристийно въздържание от храна и вода от полунощ. Важно е да се помириш с всички и, според практиката на твоята енория, да се изповядаш. Конкретната мярка за подготовка се уточнява с духовника. Подготовката не е „такса“ за Причастието, а отваряне на сърцето, за да приеме Христос.', read: '1 Кор. 11:27-29; Мат. 5:23-24' },
  { id: 'a075', cat: 'Свещено Писание', title: 'Псалом 22 – Добрият Пастир', text: 'В православната Библия (по номерацията на Септуагинта) Псалом 22 започва с думите, че Господ е нашият Пастир и нищо няма да ни липсва. В него се говори за зелени пасбища, за тихи води и за преминаване през долината на смъртната сянка без страх. Отците виждат в псалма образ на тайнствата – водата на Кръщението, помазанието и трапезата на Евхаристията. Христос по-късно казва за Себе Си: „Аз съм добрият Пастир“. Това е псалом за доверие в трудни моменти.', read: 'Пс. 22; Йоан 10:11-16' },
  { id: 'a076', cat: 'Догматика', title: 'Слизането в ада', text: 'Докато тялото на Христос лежеше в гроба, Неговата душа, съединена с Божеството, слезе в ада. Там Той проповядва на душите, които чакаха спасение от векове, и разруши властта на смъртта. Иконата на Възкресението в Православието всъщност изобразява точно това – Христос стъпва върху разбитите врати на ада и изтегля Адам и Ева от гробовете им. Няма тъмнина, до която Христос да не е слязъл. Това дава надежда на всеки, който се чувства на дъното.', read: '1 Петр. 3:18-19; Ефес. 4:8-10' },
  { id: 'a077', cat: 'Тайнства и богослужение', title: 'Как се причастяваме', text: 'Когато свещеникът изнесе Чашата и каже „Със страх Божи и вяра пристъпете“, причастяващите се приближават един по един. Ръцете се кръстосват на гърдите, дясната върху лявата, и пред Чашата не се прави кръстен знак, за да не се бутне. Казваш името си, а свещеникът те причастява с лъжичка. След това целуваш ръба на Чашата, отиваш да вземеш запивка и антидор. Денят на Причастието е ден за особено внимание, мир и благодарност.', read: 'Йоан 6:56; св. Николай Кавасила, „Животът в Христос“, кн. 4' },
  { id: 'a078', cat: 'Свещено Писание', title: 'Емануил – знамението на Исаия', text: 'Пророк Исаия, живял около осем века преди Христос, предрекъл: „Ето, Девата ще зачене и ще роди Син, и ще Го нарекат Емануил“. Името Емануил означава „Бог с нас“. Евангелист Матей пряко свързва това пророчество с рождението на Христос от Дева Мария. На друго място Исаия нарича идващото Дете „Чуден Съветник, Бог Силен, Отец на вечността, Княз на мира“. Затова Исаия често е наричан „старозаветният евангелист“.', read: 'Ис. 7:14; Ис. 9:6' },
  { id: 'a079', cat: 'Догматика', title: 'Възкресението Христово', text: 'На третия ден Христос възкръсна от мъртвите със Своето тяло – преобразено, но истинско, носещо раните от гвоздеите. Възкресението е основата на християнската вяра: без него, казва ап. Павел, вярата ни е напразна. То е първият плод на новото творение и залог за нашето бъдещо възкресение. Апостолите, които бягаха от страх, станаха безстрашни свидетели именно защото видяха Възкръсналия. Всяка неделя Църквата празнува малка Пасха в чест на това събитие.', read: '1 Кор. 15:12-22; Йоан 20' },
  { id: 'a080', cat: 'Тайнства и богослужение', title: 'Отпуст и антидор', text: 'След Причастието Църквата благодари: „Видяхме истинската Светлина, приехме Духа небесен“. Литургията завършва с отпуст – свещеникът благославя народа и споменава светиите на деня. Вярващите целуват кръста в ръката на свещеника и получават антидор – благословен хляб от просфорите, раздаван „вместо Даровете“. Антидорът се яде с благоговение, като трохите не се хвърлят. Литургията свършва в храма, но продължава в живота – като „литургия след Литургията“.', read: 'Лука 24:50-53; Мат. 5:16' },
  { id: 'a081', cat: 'Свещено Писание', title: 'Страдащият Раб Господен', text: 'В 53-та глава на книгата на пророк Исаия е описан Раб Господен, презрян и отхвърлен от хората, Който понася нашите болести и бива изранен за нашите грехове. Той е воден като агне на заколение и не отваря устата Си. Пророчеството е написано векове преди Разпятието, но го описва с поразителна точност. В Деяния апостолските ап. Филип обяснява именно този текст на етиопския велможа, проповядвайки му за Иисус. С Неговите рани, казва пророкът, ние се изцелихме.', read: 'Ис. 52:13-53:12; Деян. 8:26-39' },
  { id: 'a082', cat: 'Догматика', title: 'Богородица', text: 'Третият вселенски събор в Ефес (431 г.) нарича Дева Мария Богородица (Теотокос), защото Онзи, Когото тя роди, е Самият Бог Слово, станал човек. Това название пази преди всичко истината за Христос – че Той е едно Лице, а не двама. Богородица е най-святото от всички създания, „по-честна от херувимите“. Тя не е богиня, но е Майка на Бога и наша застъпница. Православните християни я почитат и непрестанно ѝ се молят: „Пресвета Богородице, спаси нас“.', read: 'Лука 1:26-56; св. Кирил Александрийски, Второ послание до Несторий' },
  { id: 'a083', cat: 'Тайнства и богослужение', title: 'Денонощният кръг служби', text: 'Църквата освещава всеки час от денонощието чрез служби. Литургичното денонощие започва вечерта, както в Битие: „И биде вечер, и биде утро – ден един“. Затова кръгът започва с вечерня, следват повечерие, полунощница, утреня, часове и литургия. В енорийските храмове обикновено се служат само вечерня, утреня и литургия. Целият този ритъм е израз на заповедта: „Непрестанно се молете“.', read: 'Бит. 1:5; Пс. 118:164' },
  { id: 'a084', cat: 'Свещено Писание', title: 'Пророк Йеремия', text: 'Йеремия бил призован за пророк още като младеж и се опитал да откаже, казвайки, че е твърде млад. Бог му отговорил да не се бои, защото Той е с него. Йеремия предупреждавал народа за предстоящото разрушение на Йерусалим, а за това бил подиграван, бит и хвърлен в яма. Той е наречен „плачещият пророк“, но в неговата книга има и обещание за Нов Завет, написан в сърцата. Йеремия учи на вярност към истината, дори когато тя е непопулярна.', read: 'Иер. 1:4-10; Евр. 8:8-12' },
  { id: 'a085', cat: 'Догматика', title: 'Приснодева Мария', text: 'Църквата изповядва, че Богородица е била Дева преди Рождеството, при Рождеството и след него – затова я наричаме Приснодева. Отците виждат образ на това в затворените врати на храма от видението на пророк Езекиил, през които минава само Господ. „Братята Господни“ в Евангелието според Преданието са роднини или деца на Йосиф от първия му брак. На иконите трите звезди върху мафория на Богородица напомнят за нейното вечно девство. Нейният живот е изцяло посветен на Бога.', read: 'Иез. 44:1-2; св. Йоан Дамаскин, „Точно изложение на православната вяра“, кн. 4' },
  { id: 'a086', cat: 'Тайнства и богослужение', title: 'Вечернята', text: 'Вечернята е службата, с която започва църковният ден. Тя открива с предначинателния Псалом 103, който възпява сътворението на света. Следват „Господи, воззвах към Тебе“ (Пс. 140) и кадене, напомнящо вечерната жертва в Стария Завет. Пее се древният химн „Свете тихий“ – „Светлина тиха на светата слава“, а накрая песента на праведния Симеон „Сега отпускаш“. Вечернята ни учи да завършваме деня с благодарност и покаяние.', read: 'Пс. 103; Пс. 140:2' },
  { id: 'a087', cat: 'Свещено Писание', title: 'Йезекиил и сухите кости', text: 'Пророк Йезекиил видял долина, пълна със сухи кости, и Бог го попитал дали тези кости ще оживеят. По Божията заповед пророкът проговорил над тях и костите се съединили, облекли се с плът, а Духът влязъл в тях. Това видение е обещание за възраждането на Израил и пророчество за всеобщото възкресение. Църквата го чете на утренята на Велика събота. Няма толкова „мъртво“ положение, което Божият Дух да не може да съживи.', read: 'Иез. 37:1-14; Римл. 8:11' },
  { id: 'a088', cat: 'Догматика', title: 'Почитането на светиите', text: 'Православните християни почитат светиите, но се покланят само на Бога. Светиите са живи в Христос, защото Бог не е Бог на мъртвите, а на живите. Затова можем да ги молим за застъпничество, както молим и приятел на земята да се помоли за нас. Почитта към тях всъщност е прослава на Бога, Който ги е осветил. Всеки има свой небесен покровител – този, чието име носи.', read: 'Лука 20:38; Евр. 12:1' },
  { id: 'a089', cat: 'Тайнства и богослужение', title: 'Утренята', text: 'Утренята е най-голямата служба по съдържание в денонощния кръг. Започва с Шестопсалмието – шест псалма, които се четат в тишина и при приглушени светлини. Следват „Бог е Господ и ни се яви“, четене на псалтира, а в неделя и празник – Евангелие. Пее се канон, а в него и песента на Богородица „Величи, душе моя, Господа“. Утренята завършва с Великото славословие: „Слава на Тебе, Който ни показа светлината“.', read: 'Пс. 117:27; Лука 1:46-55' },
  { id: 'a090', cat: 'Свещено Писание', title: 'Пророк Даниил', text: 'Даниил бил отведен като младеж във вавилонски плен, но запазил верността си към Бога – дори в храната. Тримата му приятели отказали да се поклонят на златния идол и били хвърлени в огнена пещ, но ангел ги запазил невредими. Сам Даниил бил хвърлен в ров с лъвове заради молитвата си, но Бог затворил устата им. Той видял и пророческо видение за „Син Човешки“, идващ с облаците небесни – името, с което Христос по-късно нарича Себе Си. Даниил е пример за дисциплина и смелост в чужда и враждебна среда.', read: 'Дан. 3; Дан. 6; Дан. 7:13-14' },
  { id: 'a091', cat: 'Догматика', title: 'Обожение – целта на живота', text: 'Според православните отци целта на човешкия живот е обожението (теозис) – съединение с Бога по благодат. Човек не става бог по природа, но става причастник на божествената природа, както желязото в огъня става огнено, без да престане да бъде желязо. Това е по-голямо от простото „отиване в рая“ – това е преобразяване на целия човек. Пътят към обожението минава през тайнствата, заповедите, молитвата и покаянието. Св. Атанасий казва: Бог стана човек, за да стане човекът бог.', read: '2 Петр. 1:4; св. Максим Изповедник, „Глави за любовта“' },
  { id: 'a092', cat: 'Тайнства и богослужение', title: 'Часовете', text: 'Часовете са кратки служби, свързани с ключови моменти от деня и от страданията на Христос. Първият час е в началото на деня, третият напомня за слизането на Светия Дух, шестият – за разпятието, а деветият – за смъртта на Христос на кръста. Всеки час съдържа три псалма, тропари и молитви. Те показват, че времето на християнина е посветено на Бога. Дори ако не можеш да ги четеш всички, можеш в тези часове да кажеш кратка молитва.', read: 'Деян. 2:15; Деян. 3:1' },
  { id: 'a093', cat: 'Свещено Писание', title: 'Пророк Йона', text: 'Бог изпратил Йона да проповядва покаяние в езическия град Ниневия, но той избягал в обратна посока. По време на буря бил хвърлен в морето и погълнат от голяма риба, в чийто корем прекарал три дни и три нощи. След като се помолил, бил изхвърлен на сушата и все пак отишъл в Ниневия, където целият град се покаял. Христос посочва Йона като знамение за Своето погребение и Възкресение на третия ден. Книгата учи, че от Бога не можеш да избягаш и че Неговата милост е за всички народи.', read: 'Йона 1-4; Мат. 12:38-41' },
  { id: 'a094', cat: 'Догматика', title: 'Благодат и синергия', text: 'Благодатта е нетварната сила на Бога, която ни се дава даром – тя не може да бъде заслужена или купена. Но Бог не спасява човека без неговото участие: нужно е и нашето свободно усилие. Отците наричат това синергия – съдействие между Бога и човека. Св. Макарий Египетски сравнява човека със земеделец: той оре и сее, но дъждът и растежът идват от Бога. Така и в духовната тренировка – ти даваш усилието, а Бог дава силата и плода.', read: 'Фил. 2:12-13; 1 Кор. 3:6-9' },
  { id: 'a095', cat: 'Тайнства и богослужение', title: 'Църковната година', text: 'Църковната година започва на 1 септември – денят, наречен Индикт или Новолетие. През нея Църквата преживява отново цялата история на спасението: от Рождество Богородично до Успението ѝ. Има два кръга празници – неподвижни, с постоянна дата, и подвижни, зависещи от датата на Пасха. Най-важните празници са Пасха и дванадесетте Велики (Господски и Богородични) празници. Да живееш по църковния календар означава да оставиш Христос да подреди и твоето време.', read: 'Лука 4:18-19; Пс. 64:12' },
  { id: 'a096', cat: 'Свещено Писание', title: 'Пророчествата за Витлеем', text: 'Пророк Михей, съвременник на Исаия, предрекъл, че от малкия град Витлеем ще излезе Владетелят на Израил, „Чийто произход е от началото, от вечни дни“. Когато мъдреците дошли в Йерусалим да търсят новородения Цар, книжниците посочили именно това пророчество. Пророк Захария пък предрекъл, че Царят ще влезе в Йерусалим кротък, яхнал осле. А пророк Малахия, последният от старозаветните пророци, предвестил Предтечата, който ще приготви пътя. Тези пророчества показват, че Христос е отговорът на вековно очакване.', read: 'Мих. 5:2; Мат. 2:1-6' },
  { id: 'a097', cat: 'Догматика', title: 'Вяра и дела', text: 'Православието не противопоставя вярата и делата, а ги вижда като едно цяло. Вярата не е само интелектуално съгласие, а доверие и вярност към Христос, които неизбежно се проявяват в живота. Ап. Яков казва, че вярата без дела е мъртва, а ап. Павел, че се спасяваме чрез благодатта посредством вярата. Двамата не си противоречат: делата не „купуват“ спасението, но са плодът и изразът на живата вяра. Без любов и дела вярата се превръща в празна идеология.', read: 'Як. 2:14-26; Ефес. 2:8-10' },
  { id: 'a098', cat: 'Тайнства и богослужение', title: 'Пасха – празник на празниците', text: 'Възкресение Христово, или Пасха, е най-големият християнски празник – „празник на празниците и тържество на тържествата“. Думата „Пасха“ идва от еврейската дума за „преминаване“ – от смърт към живот, от земята към небето. Празнува се в първата неделя след пролетното пълнолуние, по пасхалията на Православната църква. Службата започва в полунощ с шествие около храма и победния тропар „Христос воскресе из мертвих“. Цели четиридесет дни след това християните се поздравяват с „Христос воскресе!“ – „Воистина воскресе!“', read: 'Мат. 28:1-10; св. Йоан Златоуст, Огласително слово за Пасха' },
  { id: 'a099', cat: 'Свещено Писание', title: 'Макавеите и мъченичеството', text: 'Книгите на Макавеите разказват за борбата на евреите срещу езическите владетели, които искали да ги принудят да се откажат от Божия закон. Особено трогателна е историята на майка и нейните седем сина, които един след друг приели мъчения, но не нарушили Закона. Майката ги насърчавала, като им напомняла, че Бог, Който ги е създал, ще им върне живота. Църквата ги почита като светии на 1 август, в началото на Богородичния пост. Те са пример за вярност, която не се пречупва под натиск.', read: '2 Мак. 7; Евр. 11:35' },
  { id: 'a100', cat: 'Догматика', title: 'Покаянието – промяна на ума', text: 'Гръцката дума за покаяние – метаноя – означава промяна на ума, обръщане на целия живот. Покаянието не е просто съжаление или чувство на вина, а решение да се обърнеш от греха към Бога. Първата проповед на Христос започва с думите: „Покайте се, защото се приближи Царството небесно“. Отците казват, че покаянието е подновяване на кръщението и че то продължава през целия живот. Падането не е най-страшното – страшно е да останеш долу и да не станеш.', read: 'Мат. 4:17; св. Йоан Лествичник, „Лествица“, Слово 5' },
  { id: 'a101', cat: 'Тайнства и богослужение', title: 'Рождество Богородично', text: 'На 8 септември, в началото на църковната година, Църквата празнува раждането на Дева Мария. Според Преданието тя се родила от праведните Йоаким и Анна след дълги години безплодие и молитва. Нейното раждане е първата светлина на спасението – подготовката на Майката, от която ще се роди Спасителят. В българската традиция празникът е известен като Малка Богородица. Той ни учи, че Бог чува молитвите на търпеливите.', read: 'Лука 1:46-55; Пс. 44:10-12' },
  { id: 'a102', cat: 'Свещено Писание', title: 'Четирите Евангелия', text: 'Думата „Евангелие“ означава „блага вест“ – вестта за спасението чрез Иисус Христос. Църквата приема четири Евангелия – от Матей, Марк, Лука и Йоан. Първите три се наричат синоптични, защото представят живота на Христос по сходен начин, а Йоан допълва с дълбоки беседи. В иконографията евангелистите често се изобразяват със символи: Матей – с човек (ангел), Марк – с лъв, Лука – с телец, Йоан – с орел. Четирите Евангелия са като четири свидетелства за една и съща Личност.', read: 'Марк 1:1; Йоан 20:30-31' },
  { id: 'a103', cat: 'Догматика', title: 'Страстите – болест на душата', text: 'Отците наричат страсти греховните навици, които поробват човека – като чревоугодие, блуд, сребролюбие, гняв, униние и гордост. Те са изкривяване на добри сили, вложени от Бога в душата: гневът например е даден, за да се борим срещу греха, а не срещу ближния. Страстите се лекуват с противоположните добродетели, с молитва, пост и откровеност пред духовника. Това е борба за цял живот, подобна на дълга тренировъчна подготовка. Победата не идва от собствена сила, а от смирението и Божията помощ.', read: 'Гал. 5:16-24; св. Йоан Касиан Римлянин, „За осемте главни порока“' },
  { id: 'a104', cat: 'Тайнства и богослужение', title: 'Въздвижение на Светия Кръст', text: 'На 14 септември Църквата празнува Въздвижение на Честния и Животворящ Кръст. Според Преданието света царица Елена в IV век намерила в Йерусалим Кръста, на който бил разпнат Христос, и патриархът го издигнал пред народа. Той бил издигнат над множеството и всички викали „Господи, помилуй“. Денят е постен – в памет на страданията на Господа. Кръстът ни напомня, че без жертва няма победа.', read: 'Йоан 12:31-36; Гал. 6:14' },
  { id: 'a105', cat: 'Свещено Писание', title: 'Евангелието от Матей', text: 'Свети Матей бил митар – бирник, презиран от народа, преди Христос да го призове. Неговото Евангелие е написано преди всичко за юдеи, затова често цитира старозаветни пророчества и показва, че Иисус е обещаният Месия. То започва с родословието на Христос от Авраам и Давид. В него се намира Проповедта на планината, най-пълното изложение на Христовото учение. Завършва с поръката към апостолите да научат всички народи и да ги кръщават.', read: 'Мат. 9:9-13; Мат. 28:18-20' },
  { id: 'a106', cat: 'Догматика', title: 'Църквата – Тяло Христово', text: 'Църквата не е просто организация или сграда, а Тяло Христово, на което Христос е Глава. Всеки кръстен християнин е член на това Тяло, свързан с Христос и с останалите вярващи. Тя е основана от Христос и се родила видимо в деня на Петдесетница чрез слизането на Светия Дух. В Църквата чрез тайнствата се дава благодатта, която спасява. Св. Киприан Картагенски казва, че не може да има Бога за Отец онзи, който няма Църквата за майка.', read: 'Ефес. 1:22-23; 1 Кор. 12:12-27' },
  { id: 'a107', cat: 'Тайнства и богослужение', title: 'Въведение Богородично', text: 'На 21 ноември празнуваме Въведение Богородично – въвеждането на малката Мария в Йерусалимския храм. Според Преданието родителите ѝ я посветили на Бога и тя живяла при храма, в молитва и чистота. Мария, бъдещият жив храм на Бога, влиза в каменния храм. В България този ден е и Ден на християнското семейство. Празникът ни напомня, че децата растат най-добре, когато още отрано бъдат доведени при Бога.', read: 'Пс. 44:14-16; Евр. 9:1-5' },
  { id: 'a108', cat: 'Свещено Писание', title: 'Евангелието от Марк', text: 'Евангелието от Марк е най-краткото и динамично от четирите – в него често се среща думата „веднага“. Според древното Предание св. Марк записал проповедта на ап. Петър. Евангелието показва Христос преди всичко в действие – Той изцелява, изгонва бесове, укротява бурята. То отделя голямо място на последните дни и страданията на Христос. Ако искаш да прочетеш цяло Евангелие наведнъж, Марк е добро начало.', read: 'Марк 1:1-15; 1 Петр. 5:13' },
  { id: 'a109', cat: 'Догматика', title: 'Четирите белега на Църквата', text: 'В Символа на вярата изповядваме Църквата като една, свята, съборна и апостолска. Тя е една, защото Христос има едно Тяло и една вяра. Свята е, защото Глава ѝ е Христос и в нея действа Светият Дух, макар членовете ѝ да са грешници, които се лекуват. Съборна (кафолическа) означава, че в нея е пълнотата на истината и спасението за всички народи. Апостолска е, защото пази учението и приемството от апостолите.', read: 'Ефес. 4:4-6; св. Кирил Йерусалимски, „Огласителни поучения“, 18' },
  { id: 'a110', cat: 'Тайнства и богослужение', title: 'Рождество Христово', text: 'На 25 декември Църквата празнува раждането на Господ Иисус Христос във Витлеем. Бог влиза в света не в палат, а в пещера, като беззащитно Дете – това е най-дълбокото смирение. Ангелите възвестяват мир на земята, пастирите идват да се поклонят, а мъдреците от Изток Му принасят злато, ливан и смирна. Празникът се предшества от четиридесетдневен пост и от Бъдни вечер. Рождество ни казва, че Бог е „Емануил“ – Бог с нас.', read: 'Лука 2:1-20; Мат. 2:1-12' },
  { id: 'a111', cat: 'Свещено Писание', title: 'Евангелието от Лука', text: 'Свети Лука бил лекар и спътник на ап. Павел; той е автор и на книгата Деяния на апостолите. Неговото Евангелие разказва най-подробно за Благовещението, Рождеството и детството на Иисус. Само при него се намират притчите за блудния син и за милосърдния самарянин. Лука подчертава милосърдието на Христос към бедните, грешниците, жените и чужденците. Според църковното Предание той е и първият иконописец на Богородица.', read: 'Лука 1:1-4; Кол. 4:14' },
  { id: 'a112', cat: 'Догматика', title: 'Апостолското приемство', text: 'Апостолите са ръкополагали епископи, а те – свои приемници, в непрекъсната верига до днес. Това се нарича апостолско приемство и е белег на истинската Църква. Но то не е само формална линия на ръкополагания – то включва и вярност към апостолското учение. Св. Игнатий Богоносец още в началото на II век пише, че където е епископът, там е и Църквата. Затова свещеникът в твоя храм служи с благословението на епископа, свързвайки те с апостолите.', read: '2 Тим. 2:2; св. Игнатий Богоносец, Послание до смирненци' },
  { id: 'a113', cat: 'Тайнства и богослужение', title: 'Богоявление', text: 'На 6 януари празнуваме Кръщението Господне в река Йордан, наречено Богоявление, защото тогава се явила Светата Троица. Синът се кръщава, Отец свидетелства от небето, а Духът слиза като гълъб. Христос няма нужда от очищение – Той освещава водите и цялото творение. В този ден се извършва Великият водосвет, а у нас по традиция кръстът се хвърля във вода и смели мъже скачат да го извадят. Празникът е известен в България като Йордановден.', read: 'Мат. 3:13-17; Йоан 1:29-34' },
  { id: 'a114', cat: 'Свещено Писание', title: 'Евангелието от Йоан', text: 'Свети Йоан, „ученикът, когото Иисус обичаше“, написал своето Евангелие последно и е наречен Богослов. То започва с думите „В начало бе Словото“ и разкрива Божеството на Христос с особена дълбочина. В него Христос казва за Себе Си „Аз съм“ – Хлябът на живота, Светлината на света, Добрият Пастир, Възкресението и Животът, Пътят, Истината и Животът. Неговото начало се чете на пасхалната Литургия. Целта на Евангелието, казва самият Йоан, е да повярваме и вярвайки, да имаме живот.', read: 'Йоан 1:1-18; Йоан 20:31' },
  { id: 'a115', cat: 'Догматика', title: 'Вселенските събори', text: 'Православната църква признава седем Вселенски събора – от Първия в Никея (325 г.) до Седмия, отново в Никея (787 г.). На тях епископите от цялата Църква са защитавали вярата от големи ереси. Първите два събора формулират Символа на вярата, следващите изясняват учението за Христос, а Седмият утвърждава почитането на иконите. Моделът на съборите идва от Апостолския събор в Йерусалим. Решенията им Църквата приема като израз на волята на Светия Дух.', read: 'Деян. 15:6-29; св. Йоан Дамаскин, „Точно изложение на православната вяра“' },
  { id: 'a116', cat: 'Тайнства и богослужение', title: 'Сретение Господне', text: 'На 2 февруари, четиридесет дни след Рождество, Църквата празнува Сретение Господне. Дева Мария и Йосиф довеждат Младенеца в храма, според Закона. Там Го среща (сретение означава среща) старецът Симеон, който Го взема на ръце и възкликва: „Сега отпускаш Твоя раб, Владико“. Пророчица Анна също свидетелства за Него. Празникът е срещата на Стария Завет с Новия – дълго чаканото обещание се изпълнява.', read: 'Лука 2:22-40; Мал. 3:1' },
  { id: 'a117', cat: 'Свещено Писание', title: 'Св. Йоан Кръстител', text: 'Свети Йоан Кръстител, наричан Предтеча, е последният и най-голям от старозаветните пророци. Той живял в пустинята, обличал се в камилска козина и се хранел със скакалци и див мед. Проповядвал покаяние и кръщавал в Йордан, а когато видял Иисус, казал: „Ето Агнеца Божий, Който взема греха на света“. Той не се побоял да изобличи цар Ирод и за това бил обезглавен. Христос казва, че между родените от жени няма по-голям от Йоан.', read: 'Мат. 3:1-12; Мат. 11:7-11' },
  { id: 'a118', cat: 'Догматика', title: 'Арий и Никейският събор', text: 'В началото на IV век александрийският презвитер Арий започнал да учи, че Синът Божи е създание, макар и най-високото. Това би означавало, че Христос не е истински Бог и не може истински да ни спаси. През 325 г. в Никея се събрал Първият вселенски събор, който изповядал, че Синът е единосъщен с Отца. Св. Атанасий Велики прекарал години в изгнание, защитавайки тази истина. Според Преданието на събора присъствал и св. Николай Мирликийски, ревностен защитник на вярата.', read: 'Йоан 10:30; св. Атанасий Велики, „Слова против арианите“' },
  { id: 'a119', cat: 'Тайнства и богослужение', title: 'Благовещение', text: 'На 25 март празнуваме Благовещение – благата вест, която архангел Гавриил донесе на Дева Мария. Тя чу, че ще роди Сина Божи, и смирено отговори: „Ето рабинята Господня; нека ми бъде според думата ти“. В този момент Словото стана плът в нейната утроба. Празникът често се пада по време на Великия пост, но е толкова радостен, че в този ден се разрешава риба. Благовещение е „начало на нашето спасение“, както пее тропарът.', read: 'Лука 1:26-38; Ис. 7:14' },
  { id: 'a120', cat: 'Свещено Писание', title: 'Изкушенията в пустинята', text: 'След Кръщението Христос бил изведен в пустинята, където постил четиридесет дни и бил изкушаван от дявола. Първото изкушение било да превърне камъни в хляб, второто – да се хвърли от покрива на храма, а третото – да получи всички царства, ако се поклони на сатаната. Всеки път Христос отговаря с думи от Писанието. Тези изкушения обхващат плътските желания, гордостта и жаждата за власт. Христос ни показва, че Словото Божие е оръжие в духовната борба.', read: 'Мат. 4:1-11; Евр. 4:15' },
  { id: 'a121', cat: 'Догматика', title: 'Исихазмът', text: 'Исихазмът (от гр. исихия – безмълвие, покой) е древната православна традиция на вътрешна, съсредоточена молитва. Нейно сърце е Иисусовата молитва: „Господи Иисусе Христе, Сине Божий, помилуй ме, грешния“. Исихастите учат, че умът трябва да слезе в сърцето и там непрестанно да призовава Христос. През XIV век св. Григорий Палама защитил този опит и учението за нетварната светлина. Към исихастката традиция принадлежи и св. Теодосий Търновски, внесъл я в средновековна България.', read: '1 Сол. 5:17; „Добротолюбие“' },
  { id: 'a122', cat: 'Тайнства и богослужение', title: 'Вход Господен в Йерусалим', text: 'В неделята преди Пасха празнуваме Входа Господен в Йерусалим, известен у нас като Цветница. Христос влиза в града, яздейки на осле, а народът постила дрехи и клони и вика „Осанна!“. Ден преди това, в Лазарова събота, се помни възкресяването на Лазар. Вярващите държат върбови клонки, които се освещават в храма. Същият народ, който вика „Осанна“, след няколко дни ще вика „Разпни Го“ – урок за непостоянството на човешкото сърце.', read: 'Йоан 12:12-19; Зах. 9:9' },
  { id: 'a123', cat: 'Свещено Писание', title: 'Блаженствата', text: 'Проповедта на планината започва с девет блаженства – „Блажени нищите духом, защото е тяхно Царството небесно“. Христос обявява за блажени смирените, плачещите за греховете си, кротките, жадните за правда, милостивите, чистите по сърце, миротворците и гонените заради правдата. Това е напълно противоположно на мирските представи за успех. Блаженствата са като стълба, по която човек се изкачва към Бога. Те често се пеят на Литургията.', read: 'Мат. 5:1-12; Лука 6:20-23' },
  { id: 'a124', cat: 'Догматика', title: 'Смъртта и частният съд', text: 'За християнина смъртта е временно разделяне на душата от тялото, а не край на човека. След смъртта душата преминава частен съд, при който според живота си предвкусва блаженство или мъка до деня на Страшния съд. Затова Църквата се моли за починалите на третия, деветия и четиридесетия ден и на задушниците. Православието не приема учението за чистилище, но вярва, че молитвите и милостинята за починалите им помагат. Помненето на смъртта не е мрачно, а ни учи да живеем трезво днес.', read: 'Евр. 9:27; Лука 16:19-31' },
  { id: 'a125', cat: 'Тайнства и богослужение', title: 'Възнесение Господне', text: 'На четиридесетия ден след Пасха, винаги в четвъртък, празнуваме Възнесение Господне. Христос изведе учениците към Витания, благослови ги и се възнесе на небето. Двама ангели казали, че Той ще дойде отново по същия начин. Учениците се завърнали в Йерусалим „с голяма радост“, а не с тъга – защото знаели, че Той е с тях. С Възнесението човешката природа е въведена в славата на Бога.', read: 'Лука 24:50-53; Деян. 1:1-11' },
  { id: 'a126', cat: 'Свещено Писание', title: 'Обичайте враговете си', text: 'В Проповедта на планината Христос казва нещо невиждано: „Обичайте враговете си, благославяйте ония, които ви проклинат“. Той ни призовава да не отвръщаме на злото със зло. Това не е слабост, а най-високата сила – способност да не позволиш на злото да те промени. Христос Сам изпълнил това на Кръста, молейки се за разпинащите Го. Можеш да се бориш с противника на ринга с цялата си сила и пак да му желаеш доброто и да се молиш за него.', read: 'Мат. 5:38-48; Лука 23:34' },
  { id: 'a127', cat: 'Догматика', title: 'Второто пришествие', text: 'Христос ще дойде отново – не в смирение, както при Рождеството, а в слава, за да съди живи и мъртви. Денят и часът на това никой не знае, затова Христос ни призовава да бдим. Църквата предупреждава да не се увличаме в изчисления и пророкувания на дати. Вместо това всеки ден трябва да живеем така, сякаш Господ ще дойде днес. Ранните християни са се молили: „Маранатà“ – „Дойди, Господи!“', read: 'Мат. 24:30-44; Откр. 22:20' },
  { id: 'a128', cat: 'Тайнства и богослужение', title: 'Петдесетница', text: 'На петдесетия ден след Пасха Светият Дух слезе върху апостолите във вид на огнени езици. Те започнаха да говорят на различни езици и Петър произнесе първата си проповед, след която се кръстиха около три хиляди души. Затова Петдесетница се смята за рожден ден на Църквата. На вечернята в този ден вярващите коленичат за първи път след Пасха и се четат особени молитви. Празникът е и ден на Светата Троица, а следващият понеделник е посветен на Светия Дух.', read: 'Деян. 2:1-41; Йоан 7:37-39' },
  { id: 'a129', cat: 'Свещено Писание', title: 'Молитвата Господня', text: 'Когато учениците помолили Христос да ги научи да се молят, Той им дал молитвата „Отче наш“. Тя започва с обръщение към Бога като Отец и с молба за Неговото име, Царство и воля. След това идват молбите за насъщния хляб, за прошка и за избавление от лукавия. Особено важна е молбата „и прости нам дълговете ни, както и ние прощаваме на длъжниците си“ – нашата прошка е условие за Божията. Св. отци наричат тази молитва „кратко изложение на цялото Евангелие“.', read: 'Мат. 6:9-15; Лука 11:1-4' },
  { id: 'a130', cat: 'Догматика', title: 'Всеобщото възкресение', text: 'При Второто пришествие всички мъртви ще възкръснат с телата си. Телата на праведниците ще бъдат преобразени – нетленни, безсмъртни и прославени, подобно на тялото на Възкръсналия Христос. Ап. Павел сравнява това със семе, което се сее в земята и израства в нещо по-славно. Затова християните погребват телата на своите покойници с благоговение и не ги смятат за ненужна обвивка. Нашата надежда не е само „безсмъртие на душата“, а възкресение на целия човек.', read: '1 Кор. 15:35-55; Йоан 5:28-29' },
  { id: 'a131', cat: 'Тайнства и богослужение', title: 'Преображение Господне', text: 'На 6 август празнуваме Преображение Господне. Христос заведе Петър, Яков и Йоан на висока планина – според Преданието Тавор – и се преобрази пред тях: лицето Му светна като слънце. Явиха се Мойсей и Илия, представители на Закона и пророците. Това станало, за да укрепи учениците преди страданията Му. На празника се освещават грозде и плодове – знак, че Христос преобразява цялото творение.', read: 'Мат. 17:1-9; 2 Петр. 1:16-18' },
  { id: 'a132', cat: 'Свещено Писание', title: 'Притчата за сеяча', text: 'Христос разказал за сеяч, чиито семена падали на различни места: край пътя, на камениста почва, между тръни и на добра земя. Само на добрата земя семето дало плод. Сам Христос обяснява, че семето е Словото Божие, а различните почви – различните човешки сърца. Някои слушат, но веднага забравят; други се въодушевяват, но се отказват при изпитание; трети се задушават от грижи и богатство. Притчата ни пита: каква почва е моето сърце днес?', read: 'Мат. 13:1-23; Лука 8:4-15' },
  { id: 'a133', cat: 'Догматика', title: 'Страшният съд', text: 'В притчата за Страшния съд Христос показва, че хората ще бъдат съдени по любовта им – дали са нахранили гладния, посетили болния и затворника. Всичко, направено за най-малкия, е направено за Самия Христос. Съдът не е отмъщение, а разкриване на истината за това какви сме станали. Църквата чете тази притча в Месопустната неделя, преди Великия пост. Ако помним, че ще застанем пред Христос, ще бъдем по-милостиви днес.', read: 'Мат. 25:31-46; 2 Кор. 5:10' },
  { id: 'a134', cat: 'Тайнства и богослужение', title: 'Успение Богородично', text: 'На 15 август Църквата празнува Успение Богородично – кончината на Божията Майка. „Успение“ означава заспиване, защото смъртта на Богородица е тиха и светла. Според Преданието апостолите се събрали при нея и Христос Сам приел душата ѝ. Църквата вярва, че след три дни тялото ѝ било взето на небето. В България празникът е известен като Голяма Богородица, а пред него има двуседмичен пост.', read: 'Пс. 44:10-18; Лука 1:48' },
  { id: 'a135', cat: 'Свещено Писание', title: 'Притчата за блудния син', text: 'По-малкият син поискал своя дял от наследството, отишъл в далечна страна и пропилял всичко. Когато стигнал до дъното – да пасе свине и да гладува, той „дошъл на себе си“ и решил да се върне при баща си. Бащата го видял отдалеч, затичал се, прегърнал го и устроил празник. По-големият брат обаче се ядосал, защото не можел да приеме милостта на бащата. Църквата чете тази притча в неделята преди Месни заговезни, за да ни покаже, че никога не е късно да се върнем.', read: 'Лука 15:11-32; Пс. 102:8-13' },
  { id: 'a136', cat: 'Догматика', title: 'Раят и адът', text: 'Раят е вечно общение с Бога, а адът – вечно отчуждение от Него. Много православни отци учат, че Божията любов ще бъде една и съща за всички, но ще бъде преживяна различно: за обичащите – като светлина и радост, а за отхвърлилите я – като огън и мъка. Бог не иска никой да погине, но не насилва свободата на човека. Св. Исаак Сирин казва, че мъката в ада е мъката от отхвърлената любов. Затова изборът се прави тук, в този живот.', read: '1 Кор. 2:9; св. Исаак Сирин, „Слова подвижнически“' },
  { id: 'a137', cat: 'Тайнства и богослужение', title: 'Иконата – прозорец към небето', text: 'Православната икона не е обикновена картина, а свещен образ, който ни свързва с изобразения светия. Тя се пише по особени канони – обратна перспектива, златен фон, изчистени лица, които показват преобразен човек, а не естествено изображение. Иконописецът работи с молитва и пост. Когато целуваме икона, почитта се отнася към първообраза – към Христос, Богородица или светията. Иконата е „Евангелие в образи“ за всички, дори за неграмотните.', read: 'Изх. 25:18-22; св. Йоан Дамаскин, „Три слова в защита на светите икони“' },
  { id: 'a138', cat: 'Свещено Писание', title: 'Милосърдният самарянин', text: 'На въпроса „Кой е моят ближен?“ Христос отговаря с притча. Човек, нападнат от разбойници, лежал полумъртъв на пътя; свещеник и левит минали покрай него, но самарянин – от презиран народ – спрял, превързал раните му и платил за грижата му. Христос завършва с думите: „Иди и ти прави същото“. Отците тълкуват самарянина и като образ на Самия Христос, Който лекува изранения от греха човек. Ближният не е само „нашият“ човек, а всеки, който има нужда от нас.', read: 'Лука 10:25-37; 1 Йоан 3:17-18' },
  { id: 'a139', cat: 'Догматика', title: 'Символът на вярата', text: 'Никео-Цариградският символ на вярата е кратко изложение на православната вяра, утвърдено от Първия (325 г.) и Втория (381 г.) вселенски събор. Той се състои от 12 члена и се чете или пее на всяка Божествена литургия и при Кръщението. Всеки член е като стълб, на който стои цялата сграда на вярата. Добре е всеки християнин да го знае наизуст и да го чете всеки ден в утринните молитви. В следващите дни ще разгледаме неговите членове един по един.', read: 'Римл. 10:9-10; св. Кирил Йерусалимски, „Огласителни поучения“' },
  { id: 'a140', cat: 'Тайнства и богослужение', title: 'Неделя на Православието', text: 'В първата неделя на Великия пост Църквата празнува Неделя на Православието. Тя е установена през 843 г., когато окончателно е възстановено почитането на иконите след дълги години иконоборство. В този ден в храмовете често се прави литийно шествие с икони и се чете Синодикът на Православието. Празникът е благодарност за всички, които са страдали за истинската вяра. За нас той е напомняне да пазим вярата цялостна и неповредена.', read: 'Евр. 11:24-40; Йоан 1:43-51' },
  { id: 'a141', cat: 'Свещено Писание', title: 'Притчата за талантите', text: 'Един господар, преди да замине, поверил на слугите си таланти – голяма сума пари: на единия пет, на другия два, на третия един. Първите двама ги удвоили и били похвалени, а третият заровил своя талант от страх и бил осъден. Талантите са всички дарове, които Бог ни е дал – сили, способности, време, възможности. Бог не изисква от всички еднакво, а всеки да умножи това, което е получил. Талантът ти в спорта също може да служи на Бога и на хората.', read: 'Мат. 25:14-30; 1 Петр. 4:10' },
  { id: 'a142', cat: 'Догматика', title: 'Символът: член 1', text: '„Вярвам в един Бог Отец, Вседържител, Творец на небето и земята, на всичко видимо и невидимо“. Думата „вярвам“ означава лично доверие, а не просто приемане на информация. Изповядваме един Бог, в противовес на многобожието, и Го наричаме Отец. Той е Вседържител – Този, Който държи в ръцете Си целия свят. Видимото и невидимото включва както материалния свят, така и ангелите.', read: 'Бит. 1:1; Кол. 1:16' },
  { id: 'a143', cat: 'Тайнства и богослужение', title: 'Устройството на храма', text: 'Православният храм обикновено е обърнат на изток, откъдето изгрява слънцето – образ на Христос, „Слънцето на правдата“. Той се състои от три части: притвор, наос (средна част) и олтар. Притворът в древността е бил мястото на оглашените и каещите се. В наоса стоят вярващите, а олтарът е най-святото място, отделено с иконостас. Сградата сама по себе си е проповед за пътя от света към Царството Божие.', read: 'Мал. 4:2; св. Симеон Солунски, „За Божия храм“' },
  { id: 'a144', cat: 'Свещено Писание', title: 'Притчата за десетте девици', text: 'Десет девици чакали жениха със светилници в ръце; пет от тях били мъдри и взели масло, а пет – неразумни и не взели. Женихът закъснял, всички заспали, а в полунощ дошъл вик: „Ето, женихът идва!“. Неразумните останали без масло и вратата била затворена пред тях. Св. Серафим Саровски тълкува маслото като благодатта на Светия Дух, събрана чрез добри дела. Притчата се чете в началото на Страстната седмица и ни учи да бъдем винаги готови.', read: 'Мат. 25:1-13; св. Серафим Саровски, „Беседа с Мотовилов“' },
  { id: 'a145', cat: 'Догматика', title: 'Символът: член 2', text: '„И в един Господ Иисус Христос, Сина Божий, Единородния, роден от Отца преди всички векове“. Този член е най-дългият, защото срещу Арий трябвало ясно да се изповяда Божеството на Сина. Христос е „Светлина от Светлина, Бог истинен от Бог истинен, роден, несътворен, единосъщен с Отца“. Думата „единосъщен“ означава, че Синът има същата божествена природа като Отца. „Чрез Когото всичко е станало“ – Синът е Творец, а не творение.', read: 'Йоан 1:1-3; Евр. 1:3' },
  { id: 'a146', cat: 'Тайнства и богослужение', title: 'Иконостасът', text: 'Иконостасът е стена от икони, която отделя олтара от наоса. В средата са Царските двери, през които минава само свещенослужител при определени моменти, а отстрани – северните и южните (дяконски) двери. Вдясно от Царските двери е иконата на Христос, а вляво – на Богородица с Младенеца. До тях обикновено са икони на св. Йоан Кръстител и на светията или празника, на които е посветен храмът. Иконостасът не скрива, а показва небето, събрано около Христос.', read: 'Евр. 10:19-20; св. Симеон Солунски, „За Божия храм“' },
  { id: 'a147', cat: 'Свещено Писание', title: 'Митарят и фарисеят', text: 'Двама души влезли в храма да се молят: фарисей, който изброявал добрите си дела и се сравнявал с другите, и митар, който стоял отдалеч и казвал само: „Боже, бъди милостив към мене, грешника“. Христос казва, че митарят си отишъл оправдан, а фарисеят – не. Гордостта обезсмисля и най-големите подвизи, а смирението отваря вратата към Бога. С неделята на тази притча започва периодът на Триода преди Великия пост. Молитвата на митаря е в основата на Иисусовата молитва.', read: 'Лука 18:9-14; Як. 4:6' },
  { id: 'a148', cat: 'Догматика', title: 'Символът: член 3', text: '„Който заради нас, човеците, и заради нашето спасение слезе от небесата и се въплъти от Духа Светаго и Дева Мария и стана човек“. Тук е причината за всичко – „заради нас“. Бог не е бил длъжен да идва, Той дойде от любов. Въплъщението става чрез действието на Светия Дух и съгласието на Дева Мария. Затова църковните песнопения наричат Богородица „стълба небесна“, по която Бог слезе при хората.', read: 'Лука 1:35; Гал. 4:4' },
  { id: 'a149', cat: 'Тайнства и богослужение', title: 'Светият престол', text: 'В центъра на олтара стои светият престол – масата, на която се извършва Евхаристията. На него се намират Евангелието, кръст, дарохранителница и антиминс. Антиминсът е копринено платно с изображение на полагането на Христос в гроба, с вшити мощи на светия и подпис на епископа. Без антиминс не може да се служи Литургия. Престолът е образ на Божия трон и на гроба Христов едновременно.', read: 'Откр. 6:9; Евр. 13:10' },
  { id: 'a150', cat: 'Свещено Писание', title: 'Сватбата в Кана Галилейска', text: 'Първото чудо на Христос станало на сватба в Кана Галилейска, където виното свършило. Богородица забелязала това и казала на слугите: „Каквото ви каже, това направете“. Христос превърнал водата в шест каменни съда във вино, по-добро от първото. С това Той благословил брака и показал, че идва да преобрази живота ни. Думите на Богородица са най-добрият съвет към всеки християнин.', read: 'Йоан 2:1-11; Ефес. 5:31-32' },
  { id: 'a151', cat: 'Догматика', title: 'Символът: член 4', text: '„И бе разпнат за нас при Понтий Пилат, и страда, и бе погребан“. Името на римския управител е включено, за да подчертае, че това е реално историческо събитие, а не мит. Христос наистина е страдал и наистина е умрял, а не само „привидно“, както твърдели някои еретици. Отново се повтаря „за нас“ – Неговата смърт е лична за всеки от нас. Погребението свидетелства, че смъртта Му е била истинска.', read: 'Мат. 27; Ис. 53:4-5' },
  { id: 'a152', cat: 'Тайнства и богослужение', title: 'Свещенически одежди', text: 'Свещените одежди напомнят, че служителят застава не от свое име, а като служител на Христос. Дяконът носи стихар, орар и нарукавници. Свещеникът носи подризник, епитрахил (знак на свещеническата благодат), пояс, нарукавници и фелон. Епископът облича сакос, омофор, митра и панагия и държи жезъл. Цветовете се сменят според празника – например бяло за Пасха и Рождество, червено за мъчениците, тъмни цветове за поста.', read: 'Изх. 28; Пс. 131:9' },
  { id: 'a153', cat: 'Свещено Писание', title: 'Нахранването на хилядите', text: 'Пет хиляди мъже, освен жените и децата, слушали Христос в пустинно място и огладнели. Учениците имали само пет хляба и две риби, но Христос ги благословил, разчупил и раздал, и всички се наситили. Останали дванадесет пълни коша. Това е единственото чудо, разказано и в четирите Евангелия. То е предобраз на Евхаристията и ни учи, че малкото, дадено на Христос, става изобилие.', read: 'Мат. 14:13-21; Йоан 6:1-14' },
  { id: 'a154', cat: 'Догматика', title: 'Символът: член 5', text: '„И възкръсна в третия ден според Писанията“. Възкресението е сърцевината на апостолската проповед. „Според Писанията“ означава, че то е предречено в Стария Завет – например в знамението на пророк Йона. Христос е възкръснал със Своето тяло, видели са Го и са Го докосвали множество свидетели. Без този член християнството би било просто морално учение.', read: '1 Кор. 15:3-8; Мат. 12:40' },
  { id: 'a155', cat: 'Тайнства и богослужение', title: 'Кръстният знак', text: 'Кръстният знак е кратка изповед на вярата и молитва с тялото. Православните събират първите три пръста на дясната ръка – в знак на Светата Троица, а другите два притискат към дланта – в знак на двете природи на Христос. Кръстим се, като докосваме челото, корема (гърдите), дясното и след това лявото рамо. Така освещаваме ума, чувствата и силите си. Кръстът не трябва да се прави набързо, като „махане“, а внимателно и с благоговение.', read: 'Гал. 6:14; 1 Кор. 1:18' },
  { id: 'a156', cat: 'Свещено Писание', title: 'Петър върви по водата', text: 'През нощта, сред бурното море, Христос дошъл при учениците, вървейки по водата. Петър поискал и той да дойде при Него и тръгнал по водата. Но когато видял силния вятър, се уплашил и започнал да потъва, викайки: „Господи, спаси ме!“. Христос веднага протегнал ръка, хванал го и му казал: „Маловерецо, защо се усъмни?“. Докато гледаш към Христос, вървиш; когато гледаш вълните – потъваш.', read: 'Мат. 14:22-33; Пс. 68:2-3' },
  { id: 'a157', cat: 'Догматика', title: 'Символът: член 6', text: '„И възлезе на небесата и седи отдясно на Отца“. На четиридесетия ден след Възкресението Христос се възнесе пред очите на учениците. Той възлезе не само като Бог, но и с човешката Си природа – така нашата природа е въздигната до Божия престол. „Отдясно на Отца“ е образ на равна чест и власт, а не на място в пространството. Възнесението не е раздяла, защото Христос е обещал да бъде с нас до края на света.', read: 'Деян. 1:9-11; Мат. 28:20' },
  { id: 'a158', cat: 'Тайнства и богослужение', title: 'Светената вода', text: 'Светената вода (агиасма) се освещава чрез специална служба – водосвет. Великият водосвет се извършва на Богоявление, а малкият – по всяко време, при нужда. Вярващите я пият сутрин на гладно, обикновено с парченце просфора, ръсят домовете си и болните с нея. Чрез нея Божията благодат освещава ежедневния живот и пази от злото. Тя не е талисман, а благословение, което се приема с вяра и молитва.', read: 'Йоан 5:2-4; 4 Цар. 5:10-14' },
  { id: 'a159', cat: 'Свещено Писание', title: 'Възкресяването на Лазар', text: 'Лазар, приятелят на Иисус, умрял и вече четири дни лежал в гроба. Христос дошъл във Витания и заплакал заедно със скърбящите – Той не е безчувствен към нашата болка. След това застанал пред гроба и извикал: „Лазаре, излез вън!“, и мъртвият излязъл. Преди това Той казал на Марта: „Аз съм Възкресението и Животът“. Църквата помни това чудо в Лазарова събота, като увереност в общото възкресение.', read: 'Йоан 11:1-45; Йоан 11:25-26' },
  { id: 'a160', cat: 'Догматика', title: 'Символът: член 7', text: '„И пак ще дойде със слава да съди живи и мъртви, и царството Му не ще има край“. Този член ни насочва към бъдещето – към Второто пришествие. Христос, Който веднъж дойде в смирение, ще дойде отново като Цар и Съдия. Последните думи са насочени срещу учението, че Христовото царство ще свърши. Християнинът живее в напрежението между „вече“ и „още не“ – с надежда и бдителност.', read: 'Лука 1:33; Деян. 17:31' },
  { id: 'a161', cat: 'Тайнства и богослужение', title: 'Молитвата за починалите', text: 'Православната църква се моли за своите починали, защото вярва, че в Христос смъртта не разделя Църквата. Над починалия се извършва опело, а след това панихиди на третия, деветия и четиридесетия ден, на половин година и на годишнината. Освен това има общи задушници през годината – пред Месни заговезни, пред Петдесетница и пред Архангеловден. Носи се жито (коливо), което напомня за възкресението: зърното умира в земята и дава нов живот. Най-силната помощ за починалите е споменаването им на Литургия.', read: 'Йоан 12:24; 2 Мак. 12:43-45' },
  { id: 'a162', cat: 'Свещено Писание', title: 'Изцелението на слепородения', text: 'Христос срещнал човек, сляп от рождение, и учениците попитали кой е съгрешил – той или родителите му. Христос отговорил, че нито той, нито те, а за да се явят в него делата Божии. Направил кал, помазал очите му и го изпратил да се умие в къпалнята Силоам – и човекът прогледнал. Фарисеите го разпитвали и изгонили, но той смело свидетелствал: „Едно зная – бях сляп, а сега виждам“. Чудото се чете в Неделята на слепия, между Пасха и Възнесение.', read: 'Йоан 9:1-41; Ис. 35:5' },
  { id: 'a163', cat: 'Догматика', title: 'Символът: член 8', text: '„И в Духа Светаго, Господа Животворящаго, Който изхожда от Отца, Комуто се покланяме и Го славим наравно с Отца и Сина, и Който е говорил чрез пророците“. Този член е утвърден от Втория вселенски събор (381 г.) срещу онези, които отричали Божеството на Духа. Духът е наречен „Господ“ – същото име, дадено на Бога. Той е източникът на живота – и физическия, и духовния. Пророците са говорили не от себе си, а вдъхновени от Него.', read: 'Йоан 15:26; 2 Петр. 1:21' },
  { id: 'a164', cat: 'Тайнства и богослужение', title: 'Смисълът на поста', text: 'Постът не е диета, а духовна тренировка, в която тялото се учи да слуша духа. Въздържанието от месо, млечни продукти и яйца е само външната страна – по-важно е да постим от гняв, осъждане и празни думи. Сам Христос пости четиридесет дни в пустинята, преди да започне проповедта Си. Отците казват, че постът без молитва и милостиня е като птица без крила. Мярката на поста трябва да е съобразена със здравето и натоварването ти и да бъде обсъдена с духовника.', read: 'Мат. 6:16-18; Ис. 58:6-7' },
  { id: 'a165', cat: 'Свещено Писание', title: 'Деяния на апостолите', text: 'Книгата Деяния на светите апостоли, написана от св. Лука, разказва за първите години на Църквата. Започва с Възнесението и Петдесетница и описва проповедта на ап. Петър в Йерусалим. Следва мъченичеството на първомъченик Стефан и обръщането на Савел. Втората половина проследява мисионерските пътувания на ап. Павел до Рим. Деянията се четат на Литургията през пасхалния период и показват как Светият Дух създава и води Църквата.', read: 'Деян. 1:8; Деян. 2:42-47' },
  { id: 'a166', cat: 'Догматика', title: 'Символът: член 9', text: '„В една, свята, съборна и апостолска Църква“. Вярата в Църквата е част от вярата в Бога, защото Църквата е Тялото Христово. Тук не казваме, че вярваме „в“ Църквата като в божество, а че я изповядваме като дело на Бога. Тези четири свойства я отличават от човешките общества. Християнинът не може да бъде „сам със себе си“ – той е член на общност.', read: 'Мат. 16:18; 1 Тим. 3:15' },
  { id: 'a167', cat: 'Тайнства и богослужение', title: 'Великият пост', text: 'Великият пост е най-продължителният и строг пост – четиридесет дни плюс Страстната седмица преди Пасха. Започва след Неделя Сиропустна (Прошка), когато вярващите си искат прошка един от друг. През първата седмица се чете Великият покаен канон на св. Андрей Критски. Всеки ден се казва молитвата на св. Ефрем Сирин: „Господи и Владико на живота ми“. Целта на поста е да стигнем до Пасха обновени, с чисто сърце.', read: 'Мат. 6:14-21; св. Андрей Критски, Велик канон' },
  { id: 'a168', cat: 'Свещено Писание', title: 'Обръщането на апостол Павел', text: 'Савел бил ревностен фарисей, който преследвал християните и одобрил убийството на Стефан. На път за Дамаск той бил осиян от светлина от небето и чул глас: „Савле, Савле, защо Ме гониш?“. Ослепял за три дни, а после бил кръстен от Анания и прогледнал. Скоро станал най-ревностният проповедник на Христос – апостол Павел, апостолът на езичниците. Историята му показва, че никой не е твърде далеч за Божията благодат.', read: 'Деян. 9:1-22; 1 Тим. 1:12-16' },
  { id: 'a169', cat: 'Догматика', title: 'Символът: член 10', text: '„Изповядвам едно кръщение за опрощаване на греховете“. Кръщението е едно и не се повтаря, както и раждането се случва само веднъж. Чрез него се прощават всички грехове и човекът се ражда за нов живот в Христос. Тайнството на Изповедта не е второ кръщение, а възстановяване на неговата благодат. Затова денят на кръщението е най-важният рожден ден на християнина.', read: 'Ефес. 4:5; Деян. 2:38' },
  { id: 'a170', cat: 'Тайнства и богослужение', title: 'Страстната седмица', text: 'Страстната седмица е последната седмица преди Пасха, в която Църквата преживява последните дни на Христос. На Велики четвъртък се помнят Тайната вечеря и умиването на краката, а вечерта се четат дванадесетте Евангелия на Страстите. На Велики петък се изнася плащаницата – образ на Христовото тяло, положено в гроба. Велика събота е ден на тишина и очакване, в който Христос почива в гроба, а с душата Си слиза в ада. Тези служби са сред най-дълбоките и трогателни в цялата година.', read: 'Йоан 13-19; Ис. 53' },
  { id: 'a171', cat: 'Свещено Писание', title: 'Посланието към римляните', text: 'Посланието към римляните е най-систематичното от посланията на ап. Павел. В него той обяснява, че всички хора – и юдеи, и езичници – са съгрешили и имат нужда от спасение. Спасението идва чрез вярата в Иисус Христос и благодатта Божия, а не чрез делата на Закона. В глава 8 се говори за живота в Духа и за това, че нищо не може да ни отлъчи от Божията любов. Последните глави дават практически съвети за живота в общността.', read: 'Римл. 8:28-39; св. Йоан Златоуст, Беседи върху Посланието към римляните' },
  { id: 'a172', cat: 'Догматика', title: 'Символът: член 11', text: '„Чакам възкресение на мъртвите“. Думата „чакам“ изразява трепетно очакване, а не страх. Християнинът знае, че смъртта не е последната дума и че гробът ще бъде отворен. Това очакване е дало сили на хиляди мъченици да не се отрекат от Христос. То е и утеха, когато губим близки – ние се разделяме с тях временно, а не завинаги.', read: '1 Сол. 4:13-18; Дан. 12:2' },
  { id: 'a173', cat: 'Тайнства и богослужение', title: 'Рождественският пост', text: 'Рождественският (Коледният) пост продължава от 15 ноември до 24 декември. Той е по-лек от Великия пост – в повечето дни е разрешена риба, с изключение на сряда и петък и последните дни преди Рождество. Целта му е да подготви душата за посрещането на Христос. Постът завършва с Бъдни вечер, когато семейството се събира около постна трапеза с нечетен брой ястия. Той ни учи да чакаме с надежда и вътрешна тишина.', read: 'Лука 1:5-25; Ис. 9:6' },
  { id: 'a174', cat: 'Свещено Писание', title: 'Химнът на любовта', text: 'В 13-та глава на Първото послание към коринтяните ап. Павел пише, че без любов всички дарби, знания и дори жертви са нищо. Любовта е дълготърпелива, милосърдна, не завижда, не се гордее, не търси своето и не мисли зло. Тя всичко търпи и никога не отпада. Накрая апостолът казва, че от вярата, надеждата и любовта най-голяма е любовта. Можеш да опиташ да прочетеш текста, като поставиш вместо „любовта“ своето име – и да видиш къде трябва да растеш.', read: '1 Кор. 13; 1 Йоан 4:7-12' },
  { id: 'a175', cat: 'Догматика', title: 'Символът: член 12', text: '„И живот в бъдещия век. Амин“. Символът завършва с поглед към вечността – към живота в Царството Божие, който никога не свършва. Този живот вече е започнал за нас в Църквата, най-вече в Евхаристията. Думата „Амин“ означава „истина е, така да бъде“ – с нея утвърждаваме всичко изповядано. Да кажеш „Амин“ на Символа е като да подпишеш договор за целия си живот.', read: 'Откр. 21:1-5; 2 Кор. 1:20' },
  { id: 'a176', cat: 'Тайнства и богослужение', title: 'Другите постове', text: 'Освен Великия и Рождественския, Църквата има още два многодневни поста. Петровият пост започва след Неделя на всички светии и завършва на 29 юни, празника на светите апостоли Петър и Павел. Богородичният пост е от 1 до 14 август, преди Успение Богородично. Освен това почти през цялата година се пости в сряда – в памет на предателството на Юда, и в петък – в памет на Разпятието. Съществуват и еднодневни пости, като Въздвижение и Отсичането главата на св. Йоан Кръстител.', read: 'Марк 2:18-20; Деян. 13:2-3' },
  { id: 'a177', cat: 'Свещено Писание', title: 'Всеоръжието Божие', text: 'В Посланието към ефесяните ап. Павел описва християнина като воин, който се бори не против плът и кръв, а против духовете на злобата. Той изрежда бойната екипировка: пояс на истината, броня на правдата, обувки на готовността за благовестие, щит на вярата, шлем на спасението и меч на Духа, който е Словото Божие. Всичко това се облича чрез молитва във всяко време. Всеки боец знае, че без защита и подготовка не излизаш в битка. Същото важи и за духовния живот.', read: 'Ефес. 6:10-18; Пс. 90' },
  { id: 'a178', cat: 'Догматика', title: 'Иконоборството като догматичен спор', text: 'През VIII–IX век иконоборците отхвърляли иконите като идолопоклонство. Църквата отговорила, че да се изобразява Христос е възможно именно защото Невидимият Бог стана видим човек. Седмият вселенски събор (787 г.) разграничава почитането на иконите от поклонението, което принадлежи само на Бога. Почитта, отдавана на образа, преминава към първообраза – към Лицето, изобразено на иконата. Така иконоборският спор всъщност е бил спор за истинността на Въплъщението.', read: 'Кол. 1:15; св. Йоан Дамаскин, „Три слова в защита на светите икони“' },
  { id: 'a179', cat: 'Тайнства и богослужение', title: 'Свещи, кандило, тамян', text: 'Запалената свещ е нашата малка жертва и знак на молитва, която гори пред Бога. Кандилото пред иконата у дома напомня, че вярата трябва да гори постоянно, а не само в празник. Тамянът е древен знак на молитвата, която се издига към небето – един от даровете на мъдреците беше ливан. Свещите за живи и за починали се поставят на различни места в храма. Всичко това не е формалност, а начин цялото същество да участва в молитвата.', read: 'Пс. 140:2; Откр. 8:3-4' },
  { id: 'a180', cat: 'Свещено Писание', title: 'Посланието на апостол Яков', text: 'Посланието на ап. Яков, брата Господен, е изключително практично. То учи, че изпитанията изграждат търпение, а търпението прави човека съвършен. Яков предупреждава за силата на езика, който е малък член, но може да запали голям огън. Той настоява, че вярата без дела е мъртва. В това послание се намира и основата на тайнството Елеосвещение.', read: 'Як. 1:2-4; Як. 3:1-12' },
  { id: 'a181', cat: 'Догматика', title: 'Човекът – свещеник на творението', text: 'В православното разбиране човекът е мост между видимия и невидимия свят, защото има и тяло, и дух. Затова той е призван да принася творението обратно на Бога с благодарност – като свещеник. Най-ясно това се вижда в Евхаристията, където хлябът и виното, плод на земята и на човешкия труд, стават Тяло и Кръв Христови. Грижата за природата, за собственото тяло и за делата ни е част от това призвание. Всяка работа, свършена с благодарност, може да бъде принос пред Бога.', read: 'Римл. 8:19-22; св. Максим Изповедник, „Мистагогия“' },
  { id: 'a182', cat: 'Тайнства и богослужение', title: 'Домашното молитвено правило', text: 'Всеки православен християнин е призван да има свое молитвено правило – утринни и вечерни молитви, които казва всеки ден. Добре е у дома да има иконен кът, ако е възможно обърнат на изток, с кандило. Правилото може да е кратко, но трябва да е постоянно – по-добре малко всеки ден, отколкото много понякога. Св. Серафим Саровски е дал кратко правило за заети хора: по три пъти „Отче наш“ и „Богородице Дево“ и веднъж Символа на вярата. Обсъди правилото си с духовника, за да е по мярата ти.', read: 'Мат. 6:6; св. Теофан Затворник, „Какво е духовният живот и как да се настроим за него“' },
  { id: 'a183', cat: 'Свещено Писание', title: 'Откровението на Йоан', text: 'Книгата Откровение (Апокалипсис) е последната книга на Библията, написана от св. Йоан Богослов на остров Патмос. Тя е пълна с образи и символи, които разкриват крайната победа на Христос, Агнеца, над злото. Православната църква не я чете на Литургията и предупреждава да не се тълкува произволно и сензационно. Главното ѝ послание е утешително: Бог ще отрие всяка сълза и ще направи всичко ново. Книгата завършва с вика на Църквата: „Ей, дойди, Господи Иисусе!“', read: 'Откр. 1:9-18; Откр. 21:1-7' },
];
